//! TFLite FlatBuffer converter for WebNN graphs.
//!
//! Converts WebNN GraphInfo directly to TFLite flatbuffers using the
//! `flatbuffers` crate and schema generated from `protos/tflite/schema.fbs`.

// Generated by build.rs from protos/tflite/schema.fbs
include!(concat!(env!("OUT_DIR"), "/schema_generated.rs"));

use std::collections::HashMap;

use flatbuffers::{FlatBufferBuilder, WIPOffset};

use crate::error::GraphError;
use crate::graph::{DataType, Dimension, GraphInfo, OperandKind};
use crate::mlcontext::Backend;
use crate::operators::Operation;

use super::{ConvertedGraph, GraphConverter};
use crate::backends::litert::{
    is_spatial_op, transpose_hwio_to_ohwi, transpose_ihwo_to_ohwi, transpose_oihw_to_ohwi,
};

pub struct LiteRtConverter;

impl LiteRtConverter {
    pub fn new() -> Self {
        Self
    }
}

impl GraphConverter for LiteRtConverter {
    fn format(&self) -> &'static str {
        "litert"
    }

    fn convert(&self, graph: &GraphInfo) -> Result<ConvertedGraph, GraphError> {
        let bytes = build_native(graph)?;
        Ok(ConvertedGraph {
            format: "litert",
            content_type: "application/octet-stream",
            data: bytes,
            weights_data: None,
        })
    }
}

// ---- Native TFLite conversion ----

macro_rules! scalar_const {
    ($ctx:expr, $name:expr, $val:expr, $tfl_type:expr) => {{
        let bytes = match $tfl_type {
            tflite::TensorType::FLOAT16 => ($val as f32).to_le_bytes().to_vec(),
            _ => ($val as f32).to_le_bytes().to_vec(),
        };
        $ctx.add_constant($name, &[1], $tfl_type, &bytes) as i32
    }};
}

macro_rules! emit_op {
    ($ctx:expr, $ops:expr, $opcode:expr, $inp:expr, $name:expr, $shape:expr, $tfl_type:expr) => {{
        let out_idx = $ctx.add_tensor($name, $shape, $tfl_type, 0);
        let oc_idx = $ctx.add_opcode($opcode, 1);
        let iv = $ctx.fbb.create_vector(&$inp[..]);
        let ov = $ctx.fbb.create_vector(&[out_idx as i32]);
        let tfl_op = tflite::Operator::create(
            &mut $ctx.fbb,
            &tflite::OperatorArgs {
                opcode_index: oc_idx,
                inputs: Some(iv),
                outputs: Some(ov),
                builtin_options: None,
                builtin_options_type: tflite::BuiltinOptions::NONE,
                custom_options: None,
                custom_options_format: tflite::CustomOptionsFormat::FLEXBUFFERS,
                mutating_variable_inputs: None,
                intermediates: None,
                large_custom_options_offset: 0,
                large_custom_options_size: 0,
                builtin_options_2: None,
                builtin_options_2_type: tflite::BuiltinOptions2::NONE,
                debug_metadata_index: -1,
            },
        );
        $ops.push(tfl_op);
        out_idx as i32
    }};
}

// emit a reduction operator with ReducerOptions (keep_dims = true)
macro_rules! reduce_op {
    ($ctx:expr, $ops:expr, $opcode:expr, $inp:expr, $name:expr, $shape:expr, $tfl_type:expr) => {{
        let out_idx = $ctx.add_tensor($name, $shape, $tfl_type, 0);
        let oc_idx = $ctx.add_opcode($opcode, 1);
        let iv = $ctx.fbb.create_vector(&$inp[..]);
        let ov = $ctx.fbb.create_vector(&[out_idx as i32]);
        let ro = tflite::ReducerOptions::create(
            &mut $ctx.fbb,
            &tflite::ReducerOptionsArgs { keep_dims: true },
        );
        let tfl_op = tflite::Operator::create(
            &mut $ctx.fbb,
            &tflite::OperatorArgs {
                opcode_index: oc_idx,
                inputs: Some(iv),
                outputs: Some(ov),
                builtin_options: Some(ro.as_union_value()),
                builtin_options_type: tflite::BuiltinOptions::ReducerOptions,
                ..Default::default()
            },
        );
        $ops.push(tfl_op);
        out_idx as i32
    }};
}

// Normalization: (input - mean) / sqrt(variance + epsilon) * scale + bias.
macro_rules! normalize {
    ($ctx:expr, $ops:expr, $in_t:expr, $m_t:expr, $v_t:expr, $scale:expr, $bias:expr,
     $eps:expr, $out_shape:expr, $var_shape:expr, $type_:expr, $out_id:expr) => {{
        let centered = emit_op!(
            $ctx,
            $ops,
            std_op::SUB,
            [$in_t, $m_t],
            "n_centered",
            $out_shape,
            $type_
        );
        let eps_bytes = ($eps as f32).to_le_bytes().to_vec();
        let eps_t = $ctx.add_constant("n_eps", &[], $type_, &eps_bytes) as i32;
        let var_eps = emit_op!(
            $ctx,
            $ops,
            std_op::ADD,
            [$v_t, eps_t],
            "n_var_eps",
            $var_shape,
            $type_
        );
        let stddev = emit_op!(
            $ctx,
            $ops,
            std_op::SQRT,
            [var_eps],
            "n_stddev",
            $var_shape,
            $type_
        );
        let mut cur = emit_op!(
            $ctx,
            $ops,
            std_op::DIV,
            [centered, stddev],
            "n_norm",
            $out_shape,
            $type_
        );
        if let Some(st) = $scale {
            cur = emit_op!(
                $ctx,
                $ops,
                std_op::MUL,
                [cur, st],
                "n_scaled",
                $out_shape,
                $type_
            );
        }
        if let Some(bt) = $bias {
            cur = emit_op!(
                $ctx,
                $ops,
                std_op::ADD,
                [cur, bt],
                "n_out",
                $out_shape,
                $type_
            );
        }
        cur
    }};
}

// RESHAPE a 1D tensor [C] to [1,...,C,...,1] matching input rank at `axis`.
macro_rules! reshape_1d_to_axis {
    ($ctx:expr, $ops:expr, $tensor:expr, $prefix:expr, $in_shape:expr, $axis:expr, $type_:expr) => {{
        let rank = $in_shape.len() as i32;
        let ax = if $axis < 0 { rank + $axis } else { $axis };
        let mut new_shape = vec![1i32; rank as usize];
        if (ax as usize) < new_shape.len() {
            new_shape[ax as usize] = $in_shape[ax as usize];
        }
        let rs_shape_bytes: Vec<u8> = new_shape.iter().flat_map(|v| v.to_le_bytes()).collect();
        let rs_shape_t = $ctx.add_constant(
            concat!($prefix, "_rs_sh"),
            &[rank],
            tflite::TensorType::INT32,
            &rs_shape_bytes,
        );
        let rs_out = $ctx.add_tensor(concat!($prefix, "_r"), &new_shape, $type_, 0);
        let rs_oc = $ctx.add_opcode(std_op::RESHAPE, 1);
        {
            let shape_vec = $ctx.fbb.create_vector(&new_shape);
            let ro = tflite::ReshapeOptions::create(
                &mut $ctx.fbb,
                &tflite::ReshapeOptionsArgs {
                    new_shape: Some(shape_vec),
                },
            );
            let iv = $ctx.fbb.create_vector(&[$tensor as i32, rs_shape_t as i32]);
            let ov = $ctx.fbb.create_vector(&[rs_out as i32]);
            $ops.push(tflite::Operator::create(
                &mut $ctx.fbb,
                &tflite::OperatorArgs {
                    opcode_index: rs_oc,
                    inputs: Some(iv),
                    outputs: Some(ov),
                    builtin_options: Some(ro.as_union_value()),
                    builtin_options_type: tflite::BuiltinOptions::ReshapeOptions,
                    ..Default::default()
                },
            ));
        }
        rs_out as i32
    }};
}

// CAST uint8 tensor to BOOL for logical operations (Chromium pattern)
macro_rules! cast_to_bool {
    ($ctx:expr, $ops:expr, $tensor:expr, $prefix:expr, $shape:expr) => {{
        let bool_name = concat!($prefix, "_bool");
        let bool_t = $ctx.add_tensor(bool_name, $shape, tflite::TensorType::BOOL, 0);
        let cast_oc = $ctx.add_opcode(53, 1);
        let cast_iv = $ctx.fbb.create_vector(&[$tensor as i32]);
        let cast_ov = $ctx.fbb.create_vector(&[bool_t as i32]);
        $ops.push(tflite::Operator::create(
            &mut $ctx.fbb,
            &tflite::OperatorArgs {
                opcode_index: cast_oc,
                inputs: Some(cast_iv),
                outputs: Some(cast_ov),
                builtin_options: None,
                builtin_options_type: tflite::BuiltinOptions::NONE,
                ..Default::default()
            },
        ));
        bool_t as i32
    }};
}

// CAST BOOL tensor back to uint8 for logical operations (Chromium pattern)
macro_rules! cast_from_bool {
    ($ctx:expr, $ops:expr, $tensor:expr, $prefix:expr, $shape:expr) => {{
        let uint8_name = concat!($prefix, "_u8");
        let uint8_t = $ctx.add_tensor(uint8_name, $shape, tflite::TensorType::UINT8, 0);
        let cast_oc = $ctx.add_opcode(53, 1);
        let cast_iv = $ctx.fbb.create_vector(&[$tensor as i32]);
        let cast_ov = $ctx.fbb.create_vector(&[uint8_t as i32]);
        $ops.push(tflite::Operator::create(
            &mut $ctx.fbb,
            &tflite::OperatorArgs {
                opcode_index: cast_oc,
                inputs: Some(cast_iv),
                outputs: Some(cast_ov),
                builtin_options: None,
                builtin_options_type: tflite::BuiltinOptions::NONE,
                ..Default::default()
            },
        ));
        uint8_t as i32
    }};
}

struct TfliteContext<'a> {
    fbb: FlatBufferBuilder<'a>,
    tensor_offsets: Vec<WIPOffset<tflite::Tensor<'a>>>,
    opcodes: Vec<WIPOffset<tflite::OperatorCode<'a>>>,
    buffer_data: Vec<Vec<u8>>,
}

impl<'a> TfliteContext<'a> {
    fn new() -> Self {
        Self {
            fbb: FlatBufferBuilder::new(),
            tensor_offsets: Vec::new(),
            opcodes: Vec::new(),
            buffer_data: vec![Vec::new()], // buffer 0 is always empty
        }
    }

    fn add_opcode(&mut self, code: i32, version: i32) -> u32 {
        // Chromium pattern: deprecated_code = min(code, 127).
        // For codes <= 127, deprecated = code (backward compat).
        // For codes > 127, deprecated = 127 (placeholder).
        let deprecated: i8 = i8::try_from(code.min(127)).unwrap_or(0);
        let oc = tflite::OperatorCode::create(
            &mut self.fbb,
            &tflite::OperatorCodeArgs {
                deprecated_builtin_code: deprecated,
                builtin_code: tflite::BuiltinOperator(code),
                version,
                custom_code: None,
            },
        );
        let idx = self.opcodes.len() as u32;
        self.opcodes.push(oc);
        idx
    }

    fn add_tensor(
        &mut self,
        name: &str,
        shape: &[i32],
        tfl_type: tflite::TensorType,
        buffer_idx: u32,
    ) -> u32 {
        let name_offset = self.fbb.create_string(name);
        let shape_vec = self.fbb.create_vector(shape);
        let tensor = tflite::Tensor::create(
            &mut self.fbb,
            &tflite::TensorArgs {
                shape: Some(shape_vec),
                type_: tfl_type,
                buffer: buffer_idx,
                name: Some(name_offset),
                quantization: None,
                is_variable: false,
                sparsity: None,
                shape_signature: None,
                has_rank: true,
                variant_tensors: None,
            },
        );
        let idx = self.tensor_offsets.len() as u32;
        self.tensor_offsets.push(tensor);
        idx
    }

    fn add_constant(
        &mut self,
        name: &str,
        shape: &[i32],
        tfl_type: tflite::TensorType,
        data: &[u8],
    ) -> u32 {
        let buf_idx = self.buffer_data.len() as u32;
        self.buffer_data.push(data.to_vec());
        self.add_tensor(name, shape, tfl_type, buf_idx)
    }
    fn build_normalization_ops(
        &mut self,
        op: &Operation,
        tensor_map: &mut HashMap<u32, u32>,
        operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
        in_tensor: i32,
        in_shape: &[i32],
        in_type: tflite::TensorType,
    ) -> bool {
        // BatchNormalization: reshape mean/var to broadcast axis, then normalize!
        if let Operation::BatchNormalization {
            input,
            mean,
            variance,
            options,
            ..
        } = op
        {
            let opts = options.as_ref().cloned().unwrap_or_default();
            let eps = opts.epsilon as f32;
            let axis = opts.axis as i32;
            let out_id = op.outputs()[0];
            let in_t = *tensor_map.get(input).unwrap_or(input) as i32;
            let mean_t = *tensor_map.get(mean).unwrap_or(mean) as i32;
            let var_t = *tensor_map.get(variance).unwrap_or(variance) as i32;
            let scale_id = opts
                .scale
                .map(|s| *tensor_map.get(&(s as u32)).unwrap_or(&(s as u32)) as i32);
            let bias_id = opts
                .bias
                .map(|b| *tensor_map.get(&(b as u32)).unwrap_or(&(b as u32)) as i32);

            let mean_r = reshape_1d_to_axis!(
                self,
                operator_offsets,
                mean_t,
                "bn_m",
                in_shape,
                axis,
                in_type
            );
            let var_r = reshape_1d_to_axis!(
                self,
                operator_offsets,
                var_t,
                "bn_v",
                in_shape,
                axis,
                in_type
            );
            let scale_r = scale_id.map(|st| {
                reshape_1d_to_axis!(self, operator_offsets, st, "bn_sc", in_shape, axis, in_type)
            });
            let bias_r = bias_id.map(|bt| {
                reshape_1d_to_axis!(self, operator_offsets, bt, "bn_bi", in_shape, axis, in_type)
            });

            let rank = in_shape.len() as i32;
            let ax = if axis < 0 { rank + axis } else { axis };
            let mut var_shape = vec![1i32; rank as usize];
            if (ax as usize) < var_shape.len() {
                var_shape[ax as usize] = in_shape[ax as usize];
            }

            let out = normalize!(
                self,
                operator_offsets,
                in_t,
                mean_r,
                var_r,
                scale_r,
                bias_r,
                eps,
                in_shape,
                &var_shape,
                in_type,
                out_id
            );
            tensor_map.insert(out_id, out as u32);
            return true;
        }

        // InstanceNormalization: compute mean/var from input using MEAN, then normalize!
        if let Operation::InstanceNormalization { options, .. } = op {
            let opts = options.as_ref().cloned().unwrap_or_default();
            let eps = opts.epsilon as f32;
            let out_id = op.outputs()[0];
            let scale_t = opts
                .scale
                .map(|s| *tensor_map.get(&(s as u32)).unwrap_or(&(s as u32)) as i32);
            let bias_t = opts
                .bias
                .map(|b| *tensor_map.get(&(b as u32)).unwrap_or(&(b as u32)) as i32);

            let rank = in_shape.len() as i32;
            // Channel axis is always the last dim: graph is already NHWC after
            // modify_graph_for_nhwc ran in the backend before conversion.
            let channel_axis: i32 = rank - 1;
            let mut axes: Vec<i32> = (0..rank).filter(|&a| a != 0 && a != channel_axis).collect();
            if axes.is_empty() {
                axes.push(if rank > 1 { 1 } else { 0 });
            }
            let axes_buf: Vec<u8> = axes.iter().flat_map(|v| v.to_le_bytes()).collect();
            let axes_tensor = self.add_constant(
                "in_axes",
                &[axes.len() as i32],
                tflite::TensorType::INT32,
                &axes_buf,
            );

            let mut reduced_shape = in_shape.to_vec();
            for &ax in &axes {
                if (ax as usize) < reduced_shape.len() {
                    reduced_shape[ax as usize] = 1;
                }
            }

            let mean_val = reduce_op!(
                self,
                operator_offsets,
                std_op::MEAN,
                [in_tensor, axes_tensor as i32],
                "in_mean",
                &reduced_shape,
                in_type
            );
            let centered = emit_op!(
                self,
                operator_offsets,
                std_op::SUB,
                [in_tensor, mean_val],
                "in_centered",
                in_shape,
                in_type
            );
            let squared = emit_op!(
                self,
                operator_offsets,
                std_op::MUL,
                [centered, centered],
                "in_sq",
                in_shape,
                in_type
            );
            let variance = reduce_op!(
                self,
                operator_offsets,
                std_op::MEAN,
                [squared, axes_tensor as i32],
                "in_var",
                &reduced_shape,
                in_type
            );

            let out = normalize!(
                self,
                operator_offsets,
                in_tensor,
                mean_val,
                variance,
                scale_t,
                bias_t,
                eps,
                in_shape,
                &reduced_shape,
                in_type,
                out_id
            );
            tensor_map.insert(out_id, out as u32);
            return true;
        }

        // LayerNormalization: compute mean/var from input on specified axes, then normalize!
        if let Operation::LayerNormalization { options, .. } = op {
            let opts = options.as_ref().cloned().unwrap_or_default();
            let eps = opts.epsilon as f32;
            let out_id = op.outputs()[0];
            let scale_t = opts
                .scale
                .map(|s| *tensor_map.get(&(s as u32)).unwrap_or(&(s as u32)) as i32);
            let bias_t = opts
                .bias
                .map(|b| *tensor_map.get(&(b as u32)).unwrap_or(&(b as u32)) as i32);

            let norm_axes: Vec<i32> = if let Some(ref a) = opts.axes {
                a.iter().map(|&ax| ax as i32).collect()
            } else {
                vec![(in_shape.len() as i32) - 1]
            };
            let axes_buf: Vec<u8> = norm_axes.iter().flat_map(|v| v.to_le_bytes()).collect();
            let axes_tensor = self.add_constant(
                "ln_axes",
                &[norm_axes.len() as i32],
                tflite::TensorType::INT32,
                &axes_buf,
            );

            let mut reduced_shape = in_shape.to_vec();
            for &ax in &norm_axes {
                if ax >= 0 && (ax as usize) < reduced_shape.len() {
                    reduced_shape[ax as usize] = 1;
                }
            }

            let mean_val = reduce_op!(
                self,
                operator_offsets,
                std_op::MEAN,
                [in_tensor, axes_tensor as i32],
                "ln_mean",
                &reduced_shape,
                in_type
            );
            let centered = emit_op!(
                self,
                operator_offsets,
                std_op::SUB,
                [in_tensor, mean_val],
                "ln_centered",
                in_shape,
                in_type
            );
            let squared = emit_op!(
                self,
                operator_offsets,
                std_op::MUL,
                [centered, centered],
                "ln_sq",
                in_shape,
                in_type
            );
            let variance = reduce_op!(
                self,
                operator_offsets,
                std_op::MEAN,
                [squared, axes_tensor as i32],
                "ln_var",
                &reduced_shape,
                in_type
            );

            let out = normalize!(
                self,
                operator_offsets,
                in_tensor,
                mean_val,
                variance,
                scale_t,
                bias_t,
                eps,
                in_shape,
                &reduced_shape,
                in_type,
                out_id
            );
            tensor_map.insert(out_id, out as u32);
            return true;
        }

        false
    }

    fn build_logical_ops(
        &mut self,
        op: &Operation,
        tensor_map: &mut HashMap<u32, u32>,
        operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
        in_shape: &[i32],
    ) -> bool {
        if let Operation::LogicalAnd { a, b, .. } = op {
            let out_id = op.outputs()[0];
            let a_t = *tensor_map.get(a).unwrap_or(a) as i32;
            let b_t = *tensor_map.get(b).unwrap_or(b) as i32;
            let a_bool = cast_to_bool!(self, operator_offsets, a_t, "la", in_shape);
            let b_bool = cast_to_bool!(self, operator_offsets, b_t, "lb", in_shape);
            let res_bool = emit_op!(
                self,
                operator_offsets,
                std_op::LOGICAL_AND,
                [a_bool, b_bool],
                "land_bool",
                in_shape,
                tflite::TensorType::BOOL
            );
            let out = cast_from_bool!(self, operator_offsets, res_bool, "land", in_shape);
            tensor_map.insert(out_id, out as u32);
            return true;
        }
        if let Operation::LogicalOr { a, b, .. } = op {
            let out_id = op.outputs()[0];
            let a_t = *tensor_map.get(a).unwrap_or(a) as i32;
            let b_t = *tensor_map.get(b).unwrap_or(b) as i32;
            let a_bool = cast_to_bool!(self, operator_offsets, a_t, "loa", in_shape);
            let b_bool = cast_to_bool!(self, operator_offsets, b_t, "lob", in_shape);
            let res_bool = emit_op!(
                self,
                operator_offsets,
                std_op::LOGICAL_OR,
                [a_bool, b_bool],
                "lor_bool",
                in_shape,
                tflite::TensorType::BOOL
            );
            let out = cast_from_bool!(self, operator_offsets, res_bool, "lor", in_shape);
            tensor_map.insert(out_id, out as u32);
            return true;
        }
        if let Operation::LogicalXor { a, b, .. } = op {
            let out_id = op.outputs()[0];
            let a_t = *tensor_map.get(a).unwrap_or(a) as i32;
            let b_t = *tensor_map.get(b).unwrap_or(b) as i32;
            let a_bool = cast_to_bool!(self, operator_offsets, a_t, "lxoa", in_shape);
            let b_bool = cast_to_bool!(self, operator_offsets, b_t, "lxob", in_shape);
            let res_bool = emit_op!(
                self,
                operator_offsets,
                std_op::NOT_EQUAL,
                [a_bool, b_bool],
                "lxor_bool",
                in_shape,
                tflite::TensorType::BOOL
            );
            let out = cast_from_bool!(self, operator_offsets, res_bool, "lxor", in_shape);
            tensor_map.insert(out_id, out as u32);
            return true;
        }
        if let Operation::LogicalNot { input, .. } = op {
            let out_id = op.outputs()[0];
            let in_t = *tensor_map.get(input).unwrap_or(input) as i32;
            let in_bool = cast_to_bool!(self, operator_offsets, in_t, "lna", in_shape);
            let res_bool = emit_op!(
                self,
                operator_offsets,
                std_op::LOGICAL_NOT,
                [in_bool],
                "lnot_bool",
                in_shape,
                tflite::TensorType::BOOL
            );
            let out = cast_from_bool!(self, operator_offsets, res_bool, "lnot", in_shape);
            tensor_map.insert(out_id, out as u32);
            return true;
        }
        false
    }

    fn build_activation_ops(
        &mut self,
        op: &Operation,
        tensor_map: &mut HashMap<u32, u32>,
        operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
        in_tensor: i32,
        in_shape: &[i32],
        in_type: tflite::TensorType,
    ) -> bool {
        // Elu: for default alpha=1.0, falls through to TFLite ELU opcode.
        // For custom alpha: decompose as RELU(x) + alpha * (EXP(MINIMUM(x, 0)) - 1)
        if let Operation::Elu { options, .. } = op {
            let opts = options.as_ref().cloned().unwrap_or_default();
            let alpha = opts.alpha as f32;
            let out_id = op.outputs()[0];
            if (alpha - 1.0).abs() > f32::EPSILON {
                let zero = scalar_const!(self, "elu_zero", 0.0, in_type);
                let one = scalar_const!(self, "elu_one", 1.0, in_type);
                let min_out = emit_op!(
                    self,
                    operator_offsets,
                    std_op::MINIMUM,
                    [in_tensor, zero],
                    "elu_min",
                    in_shape,
                    in_type
                );
                let exp_out = emit_op!(
                    self,
                    operator_offsets,
                    std_op::EXP,
                    [min_out],
                    "elu_exp",
                    in_shape,
                    in_type
                );
                let exp_sub1 = emit_op!(
                    self,
                    operator_offsets,
                    std_op::SUB,
                    [exp_out, one],
                    "elu_exp_sub1",
                    in_shape,
                    in_type
                );
                let alpha_t = scalar_const!(self, "elu_alpha", alpha, in_type);
                let neg_part = emit_op!(
                    self,
                    operator_offsets,
                    std_op::MUL,
                    [exp_sub1, alpha_t],
                    "elu_neg",
                    in_shape,
                    in_type
                );
                let relu_out = emit_op!(
                    self,
                    operator_offsets,
                    std_op::RELU,
                    [in_tensor],
                    "elu_relu",
                    in_shape,
                    in_type
                );
                let out = emit_op!(
                    self,
                    operator_offsets,
                    std_op::ADD,
                    [relu_out, neg_part],
                    "elu_out",
                    in_shape,
                    in_type
                );
                tensor_map.insert(out_id, out as u32);
                return true;
            }
        }

        // HardSigmoid: MINIMUM(MAXIMUM(alpha*x + beta, 0), 1)
        if let Operation::HardSigmoid { options, .. } = op {
            let opts = options.as_ref().cloned().unwrap_or_default();
            let alpha_t = scalar_const!(self, "hs_alpha", opts.alpha, in_type);
            let beta_t = scalar_const!(self, "hs_beta", opts.beta, in_type);
            let zero_t = scalar_const!(self, "hs_zero", 0.0, in_type);
            let one_t = scalar_const!(self, "hs_one", 1.0, in_type);
            let mul_out = emit_op!(
                self,
                operator_offsets,
                std_op::MUL,
                [in_tensor, alpha_t],
                "hs_mul",
                in_shape,
                in_type
            );
            let add_out = emit_op!(
                self,
                operator_offsets,
                std_op::ADD,
                [mul_out, beta_t],
                "hs_add",
                in_shape,
                in_type
            );
            let max_out = emit_op!(
                self,
                operator_offsets,
                std_op::MAXIMUM,
                [add_out, zero_t],
                "hs_max",
                in_shape,
                in_type
            );
            let out = emit_op!(
                self,
                operator_offsets,
                std_op::MINIMUM,
                [max_out, one_t],
                "hs_out",
                in_shape,
                in_type
            );
            tensor_map.insert(op.outputs()[0], out as u32);
            return true;
        }

        // Softplus: LOG(ADD(EXP(x), 1.0))
        if let Operation::Softplus { .. } = op {
            let exp_out = emit_op!(
                self,
                operator_offsets,
                std_op::EXP,
                [in_tensor],
                "softplus_exp",
                in_shape,
                in_type
            );
            let one = scalar_const!(self, "softplus_one", 1.0, in_type);
            let add_out = emit_op!(
                self,
                operator_offsets,
                std_op::ADD,
                [exp_out, one],
                "softplus_add",
                in_shape,
                in_type
            );
            let out = emit_op!(
                self,
                operator_offsets,
                std_op::LOG,
                [add_out],
                "softplus_out",
                in_shape,
                in_type
            );
            tensor_map.insert(op.outputs()[0], out as u32);
            return true;
        }

        // Softsign: DIV(x, ADD(ABS(x), 1.0))
        if let Operation::Softsign { .. } = op {
            let abs_out = emit_op!(
                self,
                operator_offsets,
                std_op::ABS,
                [in_tensor],
                "softsign_abs",
                in_shape,
                in_type
            );
            let one = scalar_const!(self, "softsign_one", 1.0, in_type);
            let add_out = emit_op!(
                self,
                operator_offsets,
                std_op::ADD,
                [abs_out, one],
                "softsign_add",
                in_shape,
                in_type
            );
            let out = emit_op!(
                self,
                operator_offsets,
                std_op::DIV,
                [in_tensor, add_out],
                "softsign_out",
                in_shape,
                in_type
            );
            tensor_map.insert(op.outputs()[0], out as u32);
            return true;
        }

        // Linear: ADD(MUL(x, alpha), beta) — spec lists in both Mathematics and Activation
        if let Operation::Linear { options, .. } = op {
            let opts = options.as_ref().cloned().unwrap_or_default();
            let alpha_t = scalar_const!(self, "linear_alpha", opts.alpha, in_type);
            let beta = opts.beta as f32;
            let mul_out = emit_op!(
                self,
                operator_offsets,
                std_op::MUL,
                [in_tensor, alpha_t],
                "linear_mul",
                in_shape,
                in_type
            );
            if beta != 0.0 {
                let beta_t = scalar_const!(self, "linear_beta", beta, in_type);
                let out = emit_op!(
                    self,
                    operator_offsets,
                    std_op::ADD,
                    [mul_out, beta_t],
                    "linear_out",
                    in_shape,
                    in_type
                );
                tensor_map.insert(op.outputs()[0], out as u32);
            } else {
                tensor_map.insert(op.outputs()[0], mul_out as u32);
            }
            return true;
        }

        false
    }

    fn build_compare_ops(
        &mut self,
        op: &Operation,
        tensor_map: &mut HashMap<u32, u32>,
        operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
        in_tensor: i32,
        in_shape: &[i32],
        in_type: tflite::TensorType,
    ) -> bool {
        let out_id = op.outputs()[0];
        match op {
            Operation::IsNaN { .. } => {
                let out = emit_op!(
                    self,
                    operator_offsets,
                    std_op::NOT_EQUAL,
                    [in_tensor, in_tensor],
                    &format!("isnan_out_{out_id}"),
                    in_shape,
                    in_type
                );
                tensor_map.insert(out_id, out as u32);
                true
            }
            Operation::IsInfinite { .. } => {
                let abs_val = emit_op!(
                    self,
                    operator_offsets,
                    std_op::ABS,
                    [in_tensor],
                    &format!("isinf_abs_{out_id}"),
                    in_shape,
                    in_type
                );
                let max_const =
                    scalar_const!(self, &format!("isinf_max_{out_id}"), f32::MAX, in_type);
                let out = emit_op!(
                    self,
                    operator_offsets,
                    std_op::GREATER,
                    [abs_val, max_const],
                    &format!("isinf_out_{out_id}"),
                    in_shape,
                    in_type
                );
                tensor_map.insert(out_id, out as u32);
                true
            }
            _ => false,
        }
    }

    /// Emit a TFLite CAST operator.
    fn emit_cast_op(
        &mut self,
        operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
        in_tensor: i32,
        out_tensor: i32,
        out_type: tflite::TensorType,
    ) {
        let oc_idx = self.add_opcode(53, 1);
        let iv = self.fbb.create_vector(&[in_tensor]);
        let ov = self.fbb.create_vector(&[out_tensor]);
        let co = tflite::CastOptions::create(
            &mut self.fbb,
            &tflite::CastOptionsArgs {
                in_data_type: tflite::TensorType::INT32,
                out_data_type: out_type,
            },
        );
        operator_offsets.push(tflite::Operator::create(
            &mut self.fbb,
            &tflite::OperatorArgs {
                opcode_index: oc_idx,
                inputs: Some(iv),
                outputs: Some(ov),
                builtin_options: Some(co.as_union_value()),
                builtin_options_type: tflite::BuiltinOptions::CastOptions,
                ..Default::default()
            },
        ));
    }

    /// DequantizeLinear: (cast(input, f32) - cast(zeroPoint, f32)) * scale.
    /// QuantizeLinear: ROUND(input / scale) + zeroPoint.
    fn build_quantize_ops(
        &mut self,
        op: &Operation,
        graph: &GraphInfo,
        tensor_map: &mut HashMap<u32, u32>,
        operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
    ) -> bool {
        let out_id = op.outputs()[0];
        let out_shape: Vec<i32> = graph
            .operand(out_id)
            .map(|o| {
                o.descriptor
                    .shape
                    .iter()
                    .map(|d| match d {
                        crate::graph::Dimension::Static(v) => *v as i32,
                        _ => 1,
                    })
                    .collect()
            })
            .unwrap_or_else(|| vec![1]);
        let in_type = tflite::TensorType::FLOAT32;
        match op {
            Operation::DequantizeLinear {
                input,
                scale: scale_id,
                zero_point,
                ..
            } => {
                let in_t = *tensor_map.get(input).unwrap_or(input) as i32;
                let scale_t = *tensor_map.get(scale_id).unwrap_or(scale_id) as i32;
                let zp_id = zero_point.unwrap_or(*input);
                let zp_t = *tensor_map.get(&zp_id).unwrap_or(&zp_id) as i32;

                // Cast int inputs to float32 before arithmetic (TFLite SUB needs same type)
                let float_in =
                    self.add_tensor(&format!("dq_cast_in_{out_id}"), &out_shape, in_type, 0);
                self.emit_cast_op(
                    operator_offsets,
                    in_t,
                    float_in as i32,
                    tflite::TensorType::FLOAT32,
                );
                let float_zp =
                    self.add_tensor(&format!("dq_cast_zp_{out_id}"), &out_shape, in_type, 0);
                self.emit_cast_op(
                    operator_offsets,
                    zp_t,
                    float_zp as i32,
                    tflite::TensorType::FLOAT32,
                );

                let sub_val = emit_op!(
                    self,
                    operator_offsets,
                    std_op::SUB,
                    [float_in as i32, float_zp as i32],
                    &format!("dq_sub_{out_id}"),
                    &out_shape,
                    in_type
                );
                let out = emit_op!(
                    self,
                    operator_offsets,
                    std_op::MUL,
                    [sub_val, scale_t],
                    &format!("dq_out_{out_id}"),
                    &out_shape,
                    in_type
                );
                tensor_map.insert(out_id, out as u32);
                true
            }
            Operation::QuantizeLinear {
                input,
                scale: scale_id,
                zero_point,
                ..
            } => {
                let in_t = *tensor_map.get(input).unwrap_or(input) as i32;
                let scale_t = *tensor_map.get(scale_id).unwrap_or(scale_id) as i32;

                let div_val = emit_op!(
                    self,
                    operator_offsets,
                    std_op::DIV,
                    [in_t, scale_t],
                    &format!("q_div_{out_id}"),
                    &out_shape,
                    in_type
                );
                let round_val = emit_op!(
                    self,
                    operator_offsets,
                    std_op::ROUND,
                    [div_val],
                    &format!("q_round_{out_id}"),
                    &out_shape,
                    in_type
                );
                let cur = if let Some(zp) = zero_point {
                    let zp_t = *tensor_map.get(&zp).unwrap_or(&zp) as i32;
                    emit_op!(
                        self,
                        operator_offsets,
                        std_op::ADD,
                        [round_val, zp_t],
                        &format!("q_out_{out_id}"),
                        &out_shape,
                        in_type
                    )
                } else {
                    round_val
                };
                tensor_map.insert(out_id, cur as u32);
                true
            }
            _ => false,
        }
    }

    fn build_math_ops(
        &mut self,
        op: &Operation,
        tensor_map: &mut HashMap<u32, u32>,
        operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
        in_tensor: i32,
        in_shape: &[i32],
        in_type: tflite::TensorType,
    ) -> bool {
        // Reciprocal: DIV(1.0, x)
        if let Operation::Reciprocal { .. } = op {
            let one = scalar_const!(self, "recip_one", 1.0, in_type);
            let out = emit_op!(
                self,
                operator_offsets,
                std_op::DIV,
                [one, in_tensor],
                "reciprocal_out",
                in_shape,
                in_type
            );
            tensor_map.insert(op.outputs()[0], out as u32);
            return true;
        }

        // Clamp: MINIMUM(MAXIMUM(x, min), max)
        if let Operation::Clamp { options, .. } = op {
            let opts = options.as_ref().cloned().unwrap_or_default();
            let has_min = opts.min_value.is_some();
            let has_max = opts.max_value.is_some();
            let out_id = op.outputs()[0];
            if has_min && has_max {
                let min_val = opts
                    .min_value
                    .as_ref()
                    .and_then(|v| parse_mlnumber(Some(v)))
                    .unwrap_or(f64::MIN) as f32;
                let max_val = opts
                    .max_value
                    .as_ref()
                    .and_then(|v| parse_mlnumber(Some(v)))
                    .unwrap_or(f64::MAX) as f32;
                let min_t = scalar_const!(self, "clamp_min", min_val, in_type);
                let max_t = scalar_const!(self, "clamp_max", max_val, in_type);
                let mid = emit_op!(
                    self,
                    operator_offsets,
                    std_op::MAXIMUM,
                    [in_tensor, min_t],
                    "clamp_mid",
                    in_shape,
                    in_type
                );
                let out = emit_op!(
                    self,
                    operator_offsets,
                    std_op::MINIMUM,
                    [mid, max_t],
                    "clamp_out",
                    in_shape,
                    in_type
                );
                tensor_map.insert(out_id, out as u32);
            } else if has_min {
                let min_val = opts
                    .min_value
                    .as_ref()
                    .and_then(|v| parse_mlnumber(Some(v)))
                    .unwrap_or(f64::MIN) as f32;
                let min_t = scalar_const!(self, "clamp_min", min_val, in_type);
                let out = emit_op!(
                    self,
                    operator_offsets,
                    std_op::MAXIMUM,
                    [in_tensor, min_t],
                    "clamp_out",
                    in_shape,
                    in_type
                );
                tensor_map.insert(out_id, out as u32);
            } else if has_max {
                let max_val = opts
                    .max_value
                    .as_ref()
                    .and_then(|v| parse_mlnumber(Some(v)))
                    .unwrap_or(f64::MAX) as f32;
                let max_t = scalar_const!(self, "clamp_max", max_val, in_type);
                let out = emit_op!(
                    self,
                    operator_offsets,
                    std_op::MINIMUM,
                    [in_tensor, max_t],
                    "clamp_out",
                    in_shape,
                    in_type
                );
                tensor_map.insert(out_id, out as u32);
            } else {
                let out_tensor = self.add_tensor("clamp_out", in_shape, in_type, 0);
                let shape_bytes: Vec<u8> = in_shape.iter().flat_map(|&v| v.to_le_bytes()).collect();
                let shape_tensor = self.add_constant(
                    "clamp_shape",
                    &[in_shape.len() as i32],
                    tflite::TensorType::INT32,
                    &shape_bytes,
                );
                let oc_idx = self.add_opcode(std_op::RESHAPE, 1);
                let iv = self.fbb.create_vector(&[in_tensor, shape_tensor as i32]);
                let ov = self.fbb.create_vector(&[out_tensor as i32]);
                let shape_vec = self.fbb.create_vector(in_shape);
                let ro = tflite::ReshapeOptions::create(
                    &mut self.fbb,
                    &tflite::ReshapeOptionsArgs {
                        new_shape: Some(shape_vec),
                    },
                );
                let tfl_op = tflite::Operator::create(
                    &mut self.fbb,
                    &tflite::OperatorArgs {
                        opcode_index: oc_idx,
                        inputs: Some(iv),
                        outputs: Some(ov),
                        builtin_options: Some(ro.as_union_value()),
                        builtin_options_type: tflite::BuiltinOptions::ReshapeOptions,
                        ..Default::default()
                    },
                );
                operator_offsets.push(tfl_op);
                tensor_map.insert(out_id, out_tensor as u32);
            }
            return true;
        }

        // Tan: DIV(SIN(x), COS(x))
        if let Operation::Tan { .. } = op {
            let sin_out = emit_op!(
                self,
                operator_offsets,
                std_op::SIN,
                [in_tensor],
                "tan_sin",
                in_shape,
                in_type
            );
            let cos_out = emit_op!(
                self,
                operator_offsets,
                std_op::COS,
                [in_tensor],
                "tan_cos",
                in_shape,
                in_type
            );
            let out = emit_op!(
                self,
                operator_offsets,
                std_op::DIV,
                [sin_out, cos_out],
                "tan_out",
                in_shape,
                in_type
            );
            tensor_map.insert(op.outputs()[0], out as u32);
            return true;
        }

        // Erf: Gauss error function via Abramowitz & Stegun 7.1.26 approximation.
        // erf(x) ≈ sign(x) * (1 - 1 / p⁴) where p = 1 + a1*|x| + a2*x² + a3*|x|³ + a4*|x|⁴
        if let Operation::Erf { .. } = op {
            let out_id = op.outputs()[0];
            let p1 = scalar_const!(self, "erf_a1", 0.278393f32, in_type);
            let p2 = scalar_const!(self, "erf_a2", 0.230389f32, in_type);
            let p3 = scalar_const!(self, "erf_a3", 0.000972f32, in_type);
            let p4 = scalar_const!(self, "erf_a4", 0.078108f32, in_type);
            let one = scalar_const!(self, "erf_one", 1.0f32, in_type);

            // |x|
            let abs_x = emit_op!(
                self,
                operator_offsets,
                std_op::ABS,
                [in_tensor],
                "erf_abs",
                in_shape,
                in_type
            );

            // x²
            let x2 = emit_op!(
                self,
                operator_offsets,
                std_op::MUL,
                [abs_x, abs_x],
                "erf_x2",
                in_shape,
                in_type
            );

            // |x|³
            let x3 = emit_op!(
                self,
                operator_offsets,
                std_op::MUL,
                [abs_x, x2],
                "erf_x3",
                in_shape,
                in_type
            );

            // |x|⁴ = x² * x²
            let x4 = emit_op!(
                self,
                operator_offsets,
                std_op::MUL,
                [x2, x2],
                "erf_x4",
                in_shape,
                in_type
            );

            // a1*|x|
            let t1 = emit_op!(
                self,
                operator_offsets,
                std_op::MUL,
                [p1, abs_x],
                "erf_t1",
                in_shape,
                in_type
            );
            // a2*x²
            let t2 = emit_op!(
                self,
                operator_offsets,
                std_op::MUL,
                [p2, x2],
                "erf_t2",
                in_shape,
                in_type
            );
            // a3*|x|³
            let t3 = emit_op!(
                self,
                operator_offsets,
                std_op::MUL,
                [p3, x3],
                "erf_t3",
                in_shape,
                in_type
            );
            // a4*|x|⁴
            let t4 = emit_op!(
                self,
                operator_offsets,
                std_op::MUL,
                [p4, x4],
                "erf_t4",
                in_shape,
                in_type
            );

            // p = 1 + t1 + t2 + t3 + t4
            let p_sum12 = emit_op!(
                self,
                operator_offsets,
                std_op::ADD,
                [t1, t2],
                "erf_s12",
                in_shape,
                in_type
            );
            let p_sum34 = emit_op!(
                self,
                operator_offsets,
                std_op::ADD,
                [t3, t4],
                "erf_s34",
                in_shape,
                in_type
            );
            let p_sum1234 = emit_op!(
                self,
                operator_offsets,
                std_op::ADD,
                [p_sum12, p_sum34],
                "erf_s1234",
                in_shape,
                in_type
            );
            let p_val = emit_op!(
                self,
                operator_offsets,
                std_op::ADD,
                [one, p_sum1234],
                "erf_p",
                in_shape,
                in_type
            );

            // p²
            let p2_val = emit_op!(
                self,
                operator_offsets,
                std_op::MUL,
                [p_val, p_val],
                "erf_p2",
                in_shape,
                in_type
            );
            // p⁴
            let p4_val = emit_op!(
                self,
                operator_offsets,
                std_op::MUL,
                [p2_val, p2_val],
                "erf_p4",
                in_shape,
                in_type
            );

            // 1/p⁴
            let inv = emit_op!(
                self,
                operator_offsets,
                std_op::DIV,
                [one, p4_val],
                "erf_inv",
                in_shape,
                in_type
            );

            // 1 - 1/p⁴
            let val = emit_op!(
                self,
                operator_offsets,
                std_op::SUB,
                [one, inv],
                "erf_val",
                in_shape,
                in_type
            );

            // sign(x) * val
            let sign_x = emit_op!(
                self,
                operator_offsets,
                std_op::SIGN,
                [in_tensor],
                "erf_sign",
                in_shape,
                in_type
            );
            let out = emit_op!(
                self,
                operator_offsets,
                std_op::MUL,
                [sign_x, val],
                "erf_out",
                in_shape,
                in_type
            );
            tensor_map.insert(out_id, out as u32);
            return true;
        }

        false
    }

    fn build_matrix_ops(
        &mut self,
        op: &Operation,
        graph: &GraphInfo,
        tensor_map: &mut HashMap<u32, u32>,
        operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
        in_type: tflite::TensorType,
    ) -> bool {
        // GEMM: C = alpha * A * B + beta * C
        if let Operation::Gemm { options, .. } = op {
            let opts = options.as_ref().cloned().unwrap_or_default();
            let alpha = opts.alpha as f32;
            let beta = opts.beta as f32;

            let a_id = op.inputs().get(0).copied().unwrap_or(0);
            let b_id = op.inputs().get(1).copied().unwrap_or(0);
            let c_id = opts.c.map(|c| c as u32);
            let a_tensor = *tensor_map.get(&a_id).unwrap_or(&a_id) as i32;
            let b_tensor = *tensor_map.get(&b_id).unwrap_or(&b_id) as i32;

            let a_shape = graph
                .operand(a_id)
                .map(|o| {
                    o.descriptor
                        .shape
                        .iter()
                        .map(|d| match d {
                            crate::graph::Dimension::Static(v) => *v as i32,
                            _ => 1,
                        })
                        .collect::<Vec<_>>()
                })
                .unwrap_or(vec![1, 1]);
            let b_shape = graph
                .operand(b_id)
                .map(|o| {
                    o.descriptor
                        .shape
                        .iter()
                        .map(|d| match d {
                            crate::graph::Dimension::Static(v) => *v as i32,
                            _ => 1,
                        })
                        .collect::<Vec<_>>()
                })
                .unwrap_or(vec![1, 1]);

            let mut a_cur_tensor = a_tensor;
            let mut a_cur_shape = a_shape.clone();

            if opts.a_transpose && a_cur_shape.len() >= 2 {
                let m = a_cur_shape[a_cur_shape.len() - 2];
                let k = a_cur_shape[a_cur_shape.len() - 1];
                let r = a_cur_shape.len();
                let mut perm: Vec<i32> = (0..r as i32).collect();
                perm[r - 2] = (r - 1) as i32;
                perm[r - 1] = (r - 2) as i32;
                let mut transposed_shape = a_cur_shape.clone();
                transposed_shape[r - 2] = k;
                transposed_shape[r - 1] = m;
                let perm_bytes: Vec<u8> = perm.iter().flat_map(|v| v.to_le_bytes()).collect();
                let perm_tensor = self.add_constant(
                    "gemm_a_perm",
                    &[perm.len() as i32],
                    tflite::TensorType::INT32,
                    &perm_bytes,
                );
                a_cur_tensor = emit_op!(
                    self,
                    operator_offsets,
                    std_op::TRANSPOSE,
                    [a_cur_tensor, perm_tensor as i32],
                    "gemm_a_t",
                    &transposed_shape,
                    in_type
                );
                a_cur_shape = transposed_shape;
            }

            let mut b_cur_tensor = b_tensor;
            let mut b_cur_shape = b_shape.clone();

            if opts.b_transpose && b_cur_shape.len() >= 2 {
                let k = b_cur_shape[b_cur_shape.len() - 2];
                let n = b_cur_shape[b_cur_shape.len() - 1];
                let r = b_cur_shape.len();
                let mut perm: Vec<i32> = (0..r as i32).collect();
                perm[r - 2] = (r - 1) as i32;
                perm[r - 1] = (r - 2) as i32;
                let mut transposed_shape = b_cur_shape.clone();
                transposed_shape[r - 2] = n;
                transposed_shape[r - 1] = k;
                let perm_bytes: Vec<u8> = perm.iter().flat_map(|v| v.to_le_bytes()).collect();
                let perm_tensor = self.add_constant(
                    "gemm_b_perm",
                    &[perm.len() as i32],
                    tflite::TensorType::INT32,
                    &perm_bytes,
                );
                b_cur_tensor = emit_op!(
                    self,
                    operator_offsets,
                    std_op::TRANSPOSE,
                    [b_cur_tensor, perm_tensor as i32],
                    "gemm_b_t",
                    &transposed_shape,
                    in_type
                );
                b_cur_shape = transposed_shape;
            }

            let a_m = a_cur_shape[a_cur_shape.len() - 2];
            let _a_k = a_cur_shape[a_cur_shape.len() - 1];
            let _b_k = b_cur_shape[b_cur_shape.len() - 2];
            let b_n = b_cur_shape[b_cur_shape.len() - 1];

            let a_batch = if a_cur_shape.len() > 2 {
                &a_cur_shape[..a_cur_shape.len() - 2]
            } else {
                &[]
            };
            let b_batch = if b_cur_shape.len() > 2 {
                &b_cur_shape[..b_cur_shape.len() - 2]
            } else {
                &[]
            };
            let mut out_shape: Vec<i32> = Vec::new();
            let max_batch = a_batch.len().max(b_batch.len());
            for i in 0..max_batch {
                let a_dim = if i < a_batch.len() {
                    a_batch[a_batch.len() - 1 - i]
                } else {
                    1
                };
                let b_dim = if i < b_batch.len() {
                    b_batch[b_batch.len() - 1 - i]
                } else {
                    1
                };
                out_shape.push(a_dim.max(b_dim));
            }
            out_shape.push(a_m);
            out_shape.push(b_n);

            let mut cur_tensor = emit_op!(
                self,
                operator_offsets,
                std_op::BATCH_MATMUL,
                [a_cur_tensor, b_cur_tensor],
                "gemm_matmul",
                &out_shape,
                in_type
            );

            if (alpha - 1.0).abs() > f32::EPSILON {
                let alpha_t = scalar_const!(self, "gemm_alpha", alpha, in_type);
                cur_tensor = emit_op!(
                    self,
                    operator_offsets,
                    std_op::MUL,
                    [cur_tensor, alpha_t],
                    "gemm_alpha_out",
                    &out_shape,
                    in_type
                );
            }

            if beta != 0.0 && c_id.is_some() {
                let c_tensor = *tensor_map.get(&c_id.unwrap()).unwrap_or(&c_id.unwrap()) as i32;
                if (beta - 1.0).abs() > f32::EPSILON {
                    let beta_t = scalar_const!(self, "gemm_beta", beta, in_type);
                    let c_scaled = emit_op!(
                        self,
                        operator_offsets,
                        std_op::MUL,
                        [c_tensor, beta_t],
                        "gemm_c_scaled",
                        &out_shape,
                        in_type
                    );
                    cur_tensor = emit_op!(
                        self,
                        operator_offsets,
                        std_op::ADD,
                        [cur_tensor, c_scaled],
                        "gemm_out",
                        &out_shape,
                        in_type
                    );
                } else {
                    cur_tensor = emit_op!(
                        self,
                        operator_offsets,
                        std_op::ADD,
                        [cur_tensor, c_tensor],
                        "gemm_out",
                        &out_shape,
                        in_type
                    );
                }
            }

            tensor_map.insert(op.outputs()[0], cur_tensor as u32);
            return true;
        }
        false
    }

    fn build_reduce_ops(
        &mut self,
        op: &Operation,
        tensor_map: &mut HashMap<u32, u32>,
        operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
        in_tensor: i32,
        in_shape: &[i32],
        in_type: tflite::TensorType,
    ) -> bool {
        let (axes_opt, keep_dims) = match op {
            Operation::ReduceL1 { options, .. }
            | Operation::ReduceL2 { options, .. }
            | Operation::ReduceLogSum { options, .. }
            | Operation::ReduceLogSumExp { options, .. }
            | Operation::ReduceSumSquare { options, .. } => {
                let opts = options.as_ref();
                let axes = opts.and_then(|o| o.axes.clone());
                let kd = opts.map(|o| o.keep_dimensions).unwrap_or(true);
                (axes, kd)
            }
            _ => return false,
        };

        let out_id = op.outputs()[0];
        let rank = in_shape.len() as i32;
        let axes: Vec<i32> = match &axes_opt {
            Some(a) if !a.is_empty() => a.iter().map(|&v| v as i32).collect(),
            Some(_) => {
                // Empty axes = identity: emit RESHAPE to alias output to input.
                let out_tensor =
                    self.add_tensor(&format!("reduce_ident_{out_id}"), in_shape, in_type, 0);
                let shape_bytes: Vec<u8> = in_shape.iter().flat_map(|&v| v.to_le_bytes()).collect();
                let shape_const = self.add_constant(
                    "reduce_ident_shape",
                    &[in_shape.len() as i32],
                    tflite::TensorType::INT32,
                    &shape_bytes,
                );
                let oc_idx = self.add_opcode(std_op::RESHAPE, 1);
                let iv = self.fbb.create_vector(&[in_tensor, shape_const as i32]);
                let ov = self.fbb.create_vector(&[out_tensor as i32]);
                let shape_vec = self.fbb.create_vector(in_shape);
                let ro = tflite::ReshapeOptions::create(
                    &mut self.fbb,
                    &tflite::ReshapeOptionsArgs {
                        new_shape: Some(shape_vec),
                    },
                );
                let tfl_op = tflite::Operator::create(
                    &mut self.fbb,
                    &tflite::OperatorArgs {
                        opcode_index: oc_idx,
                        inputs: Some(iv),
                        outputs: Some(ov),
                        builtin_options: Some(ro.as_union_value()),
                        builtin_options_type: tflite::BuiltinOptions::ReshapeOptions,
                        ..Default::default()
                    },
                );
                operator_offsets.push(tfl_op);
                tensor_map.insert(out_id, out_tensor as u32);
                return true;
            }
            None => (0..rank).collect(),
        };
        let axes_bytes: Vec<u8> = axes.iter().flat_map(|v| v.to_le_bytes()).collect();
        let axes_tensor = self.add_constant(
            "reduce_r_axes",
            &[axes.len() as i32],
            tflite::TensorType::INT32,
            &axes_bytes,
        );

        // Build the reduced shape for the intermediate output
        let mut reduced_shape = in_shape.to_vec();
        for &ax in &axes {
            if (ax as usize) < reduced_shape.len() {
                if keep_dims {
                    reduced_shape[ax as usize] = 1;
                } else {
                    reduced_shape.remove(ax as usize);
                }
            }
        }
        if reduced_shape.is_empty() {
            reduced_shape.push(1); // scalar result
        }

        let prefix = match op {
            Operation::ReduceL1 { .. } => "rl1",
            Operation::ReduceL2 { .. } => "rl2",
            Operation::ReduceLogSum { .. } => "rls",
            Operation::ReduceLogSumExp { .. } => "rlse",
            Operation::ReduceSumSquare { .. } => "rss",
            _ => "red",
        };

        let cur = match op {
            Operation::ReduceL1 { .. } => {
                let abs_val = emit_op!(
                    self,
                    operator_offsets,
                    std_op::ABS,
                    [in_tensor],
                    &format!("{prefix}_abs"),
                    in_shape,
                    in_type
                );
                emit_op!(
                    self,
                    operator_offsets,
                    std_op::SUM,
                    [abs_val, axes_tensor as i32],
                    &format!("{prefix}_sum"),
                    &reduced_shape,
                    in_type
                )
            }
            Operation::ReduceL2 { .. } => {
                // rsqrt(x*x) or just one path: mul→sum→sqrt
                // Actually: sqrt(sum(x*x)) — wait that's the Frobenius norm.
                // Per WebNN: reduceL2 = sqrt(reduce_sum_square(x)).
                // So: sum(x*x, axes) then sqrt.
                // emit_op! / reduce_op! can't handle SUM with axes parameter,
                // so we inline the reduction.
                let squared = emit_op!(
                    self,
                    operator_offsets,
                    std_op::MUL,
                    [in_tensor, in_tensor],
                    &format!("{prefix}_sq"),
                    in_shape,
                    in_type
                );
                let sum_tensor =
                    self.add_tensor(&format!("{prefix}_sum"), &reduced_shape, in_type, 0);
                let oc_sum = self.add_opcode(std_op::SUM, 1);
                let iv_sum = self.fbb.create_vector(&[squared, axes_tensor as i32]);
                let ov_sum = self.fbb.create_vector(&[sum_tensor as i32]);
                let ro = tflite::ReducerOptions::create(
                    &mut self.fbb,
                    &tflite::ReducerOptionsArgs { keep_dims },
                );
                operator_offsets.push(tflite::Operator::create(
                    &mut self.fbb,
                    &tflite::OperatorArgs {
                        opcode_index: oc_sum,
                        inputs: Some(iv_sum),
                        outputs: Some(ov_sum),
                        builtin_options: Some(ro.as_union_value()),
                        builtin_options_type: tflite::BuiltinOptions::ReducerOptions,
                        ..Default::default()
                    },
                ));
                emit_op!(
                    self,
                    operator_offsets,
                    std_op::SQRT,
                    [sum_tensor as i32],
                    &format!("{prefix}_sqrt"),
                    &reduced_shape,
                    in_type
                )
            }
            Operation::ReduceLogSum { .. } => {
                let sum_val = emit_op!(
                    self,
                    operator_offsets,
                    std_op::SUM,
                    [in_tensor, axes_tensor as i32],
                    &format!("{prefix}_sum"),
                    &reduced_shape,
                    in_type
                );
                emit_op!(
                    self,
                    operator_offsets,
                    std_op::LOG,
                    [sum_val],
                    &format!("{prefix}_log"),
                    &reduced_shape,
                    in_type
                )
            }
            Operation::ReduceLogSumExp { .. } => {
                // Stable: log(sum(exp(x - max))) + max to avoid overflow/underflow.
                // Step 1: reduce_max to get max over reduction axes
                let max_tensor =
                    self.add_tensor(&format!("{prefix}_max"), &reduced_shape, in_type, 0);
                let oc_max = self.add_opcode(std_op::REDUCE_MAX, 1);
                let iv_max = self.fbb.create_vector(&[in_tensor, axes_tensor as i32]);
                let ov_max = self.fbb.create_vector(&[max_tensor as i32]);
                let ro = tflite::ReducerOptions::create(
                    &mut self.fbb,
                    &tflite::ReducerOptionsArgs { keep_dims },
                );
                operator_offsets.push(tflite::Operator::create(
                    &mut self.fbb,
                    &tflite::OperatorArgs {
                        opcode_index: oc_max,
                        inputs: Some(iv_max),
                        outputs: Some(ov_max),
                        builtin_options: Some(ro.as_union_value()),
                        builtin_options_type: tflite::BuiltinOptions::ReducerOptions,
                        ..Default::default()
                    },
                ));

                // x - max (with broadcast: if keep_dims, TFLite handles; else expand)
                let stabilized = if keep_dims {
                    emit_op!(
                        self,
                        operator_offsets,
                        std_op::SUB,
                        [in_tensor, max_tensor as i32],
                        &format!("{prefix}_stab"),
                        in_shape,
                        in_type
                    )
                } else {
                    // Expand max from reduced shape back to full input shape
                    let expanded =
                        self.add_tensor(&format!("{prefix}_max_expand"), in_shape, in_type, 0);
                    let shape_bytes: Vec<u8> =
                        in_shape.iter().flat_map(|&v| v.to_le_bytes()).collect();
                    let shape_const = self.add_constant(
                        &format!("{prefix}_expand_shape"),
                        &[in_shape.len() as i32],
                        tflite::TensorType::INT32,
                        &shape_bytes,
                    );
                    let oc_exp = self.add_opcode(std_op::BROADCAST_TO, 1);
                    let iv_exp = self
                        .fbb
                        .create_vector(&[max_tensor as i32, shape_const as i32]);
                    let ov_exp = self.fbb.create_vector(&[expanded as i32]);
                    operator_offsets.push(tflite::Operator::create(
                        &mut self.fbb,
                        &tflite::OperatorArgs {
                            opcode_index: oc_exp,
                            inputs: Some(iv_exp),
                            outputs: Some(ov_exp),
                            builtin_options: None,
                            builtin_options_type: tflite::BuiltinOptions::NONE,
                            ..Default::default()
                        },
                    ));
                    emit_op!(
                        self,
                        operator_offsets,
                        std_op::SUB,
                        [in_tensor, expanded as i32],
                        &format!("{prefix}_stab"),
                        in_shape,
                        in_type
                    )
                };
                // exp(x - max)
                let exp_val = emit_op!(
                    self,
                    operator_offsets,
                    std_op::EXP,
                    [stabilized],
                    &format!("{prefix}_exp"),
                    in_shape,
                    in_type
                );
                // sum(exp(x - max))
                let sum_val = emit_op!(
                    self,
                    operator_offsets,
                    std_op::SUM,
                    [exp_val, axes_tensor as i32],
                    &format!("{prefix}_sum"),
                    &reduced_shape,
                    in_type
                );
                // log(sum)
                let log_val = emit_op!(
                    self,
                    operator_offsets,
                    std_op::LOG,
                    [sum_val],
                    &format!("{prefix}_log"),
                    &reduced_shape,
                    in_type
                );
                // + max
                emit_op!(
                    self,
                    operator_offsets,
                    std_op::ADD,
                    [log_val, max_tensor as i32],
                    &format!("{prefix}_out"),
                    &reduced_shape,
                    in_type
                )
            }
            Operation::ReduceSumSquare { .. } => {
                let squared = emit_op!(
                    self,
                    operator_offsets,
                    std_op::MUL,
                    [in_tensor, in_tensor],
                    &format!("{prefix}_sq"),
                    in_shape,
                    in_type
                );
                emit_op!(
                    self,
                    operator_offsets,
                    std_op::SUM,
                    [squared, axes_tensor as i32],
                    &format!("{prefix}_sum"),
                    &reduced_shape,
                    in_type
                )
            }
            _ => return false,
        };
        tensor_map.insert(out_id, cur as u32);
        true
    }

    /// Identity: emit RESHAPE with same shape (Chromium/Servo approach).
    fn build_identity_op(
        &mut self,
        op: &Operation,
        graph: &GraphInfo,
        tensor_map: &mut HashMap<u32, u32>,
        operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
    ) -> bool {
        if let Operation::Identity { input, outputs, .. } = op {
            let input_tensor = *tensor_map.get(input).unwrap_or(input);
            for &out_id in outputs {
                let (out_shape, out_type) = graph
                    .operand(out_id)
                    .map(|o| {
                        let shape: Vec<i32> = o
                            .descriptor
                            .shape
                            .iter()
                            .map(|d| match d {
                                crate::graph::Dimension::Static(v) => *v as i32,
                                _ => -1,
                            })
                            .collect();
                        (
                            shape,
                            datatype_to_tflite(o.descriptor.data_type).expect("unsupported dtype"),
                        )
                    })
                    .unwrap_or((vec![], tflite::TensorType::FLOAT32));
                let out_tensor =
                    self.add_tensor(&format!("identity_out_{out_id}"), &out_shape, out_type, 0);
                let shape_bytes: Vec<u8> =
                    out_shape.iter().flat_map(|&v| v.to_le_bytes()).collect();
                let shape_tensor = self.add_constant(
                    "identity_shape",
                    &[out_shape.len() as i32],
                    tflite::TensorType::INT32,
                    &shape_bytes,
                );
                let oc_idx = self.add_opcode(std_op::RESHAPE, 1);
                let iv = self
                    .fbb
                    .create_vector(&[input_tensor as i32, shape_tensor as i32]);
                let ov = self.fbb.create_vector(&[out_tensor as i32]);
                let shape_vec = self.fbb.create_vector(&out_shape);
                let ro = tflite::ReshapeOptions::create(
                    &mut self.fbb,
                    &tflite::ReshapeOptionsArgs {
                        new_shape: Some(shape_vec),
                    },
                );
                let tfl_op = tflite::Operator::create(
                    &mut self.fbb,
                    &tflite::OperatorArgs {
                        opcode_index: oc_idx,
                        inputs: Some(iv),
                        outputs: Some(ov),
                        builtin_options: Some(ro.as_union_value()),
                        builtin_options_type: tflite::BuiltinOptions::ReshapeOptions,
                        ..Default::default()
                    },
                );
                operator_offsets.push(tfl_op);
                tensor_map.insert(out_id, out_tensor as u32);
            }
            return true;
        }
        false
    }

    /// Softmax: TFLite only supports last-axis. TRANSPOSE workaround for non-last-axis.
    fn build_softmax_op(
        &mut self,
        op: &Operation,
        tensor_map: &HashMap<u32, u32>,
        operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
        in_tensor: i32,
        in_shape: &[i32],
        in_type: tflite::TensorType,
    ) -> bool {
        if let Operation::Softmax { axis, .. } = op {
            let rank = in_shape.len() as i32;
            if rank > 0 && *axis as i32 != rank - 1 {
                let last = (rank - 1) as usize;
                let mut perm: Vec<i32> = (0..rank).collect();
                perm.swap(*axis as usize, last);
                let mid_shape: Vec<i32> = perm.iter().map(|&p| in_shape[p as usize]).collect();
                let mut inv_perm: Vec<i32> = vec![0; rank as usize];
                for (i, &p) in perm.iter().enumerate() {
                    inv_perm[p as usize] = i as i32;
                }

                let perm_b = perm
                    .iter()
                    .flat_map(|&v| v.to_le_bytes())
                    .collect::<Vec<_>>();
                let perm_t = self.add_constant(
                    "sm_perm",
                    &[rank as i32],
                    tflite::TensorType::INT32,
                    &perm_b,
                );
                let mid_t = self.add_tensor("sm_mid", &mid_shape, in_type, 0);
                let oc_t = self.add_opcode(std_op::TRANSPOSE, 1);
                let iv_t = self.fbb.create_vector(&[in_tensor, perm_t as i32]);
                let ov_t = self.fbb.create_vector(&[mid_t as i32]);
                operator_offsets.push(tflite::Operator::create(
                    &mut self.fbb,
                    &tflite::OperatorArgs {
                        opcode_index: oc_t,
                        inputs: Some(iv_t),
                        outputs: Some(ov_t),
                        builtin_options: None,
                        builtin_options_type: tflite::BuiltinOptions::NONE,
                        ..Default::default()
                    },
                ));

                let mid2 = self.add_tensor("sm_mid2", &mid_shape, in_type, 0);
                let oc_s = self.add_opcode(std_op::SOFTMAX, 1);
                let iv_s = self.fbb.create_vector(&[mid_t as i32]);
                let ov_s = self.fbb.create_vector(&[mid2 as i32]);
                let so = tflite::SoftmaxOptions::create(
                    &mut self.fbb,
                    &tflite::SoftmaxOptionsArgs { beta: 1.0 },
                );
                operator_offsets.push(tflite::Operator::create(
                    &mut self.fbb,
                    &tflite::OperatorArgs {
                        opcode_index: oc_s,
                        inputs: Some(iv_s),
                        outputs: Some(ov_s),
                        builtin_options: Some(so.as_union_value()),
                        builtin_options_type: tflite::BuiltinOptions::SoftmaxOptions,
                        ..Default::default()
                    },
                ));

                let inv_perm_b = inv_perm
                    .iter()
                    .flat_map(|&v| v.to_le_bytes())
                    .collect::<Vec<_>>();
                let inv_perm_t = self.add_constant(
                    "sm_inv_perm",
                    &[rank as i32],
                    tflite::TensorType::INT32,
                    &inv_perm_b,
                );
                let out_t = *tensor_map.get(&op.outputs()[0]).unwrap_or(&op.outputs()[0]) as i32;
                let oc_i = self.add_opcode(std_op::TRANSPOSE, 1);
                let iv_i = self.fbb.create_vector(&[mid2 as i32, inv_perm_t as i32]);
                let ov_i = self.fbb.create_vector(&[out_t]);
                operator_offsets.push(tflite::Operator::create(
                    &mut self.fbb,
                    &tflite::OperatorArgs {
                        opcode_index: oc_i,
                        inputs: Some(iv_i),
                        outputs: Some(ov_i),
                        builtin_options: None,
                        builtin_options_type: tflite::BuiltinOptions::NONE,
                        ..Default::default()
                    },
                ));
                return true;
            }
        }
        false
    }

    /// Slice: use SLICE (no strides) or STRIDED_SLICE (with strides).
    /// Returns Some(true) if op was fully handled (strided), Some(false) if inputs were added,
    /// None if this is not a slice op.
    fn build_slice_op(
        &mut self,
        op: &Operation,
        tensor_map: &HashMap<u32, u32>,
        operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
        in_tensor: i32,
        inputs: &mut Vec<i32>,
    ) -> Option<bool> {
        if let Operation::Slice {
            starts,
            sizes,
            options,
            ..
        } = op
        {
            let strides: Vec<u32> = options
                .as_ref()
                .map(|o| o.strides.clone())
                .unwrap_or_default();
            let has_strides = !strides.is_empty() && strides.iter().any(|&s| s != 1);
            let begins_bytes: Vec<u8> = starts
                .iter()
                .flat_map(|&v| (v as i32).to_le_bytes())
                .collect();
            let begins_tensor = self.add_constant(
                "slice_begins",
                &[starts.len() as i32],
                tflite::TensorType::INT32,
                &begins_bytes,
            );
            let begins_idx = begins_tensor as i32;
            if has_strides {
                let ends: Vec<i32> = starts
                    .iter()
                    .zip(sizes.iter())
                    .zip(strides.iter())
                    .map(|((&s, sz), &stride)| {
                        s as i32
                            + crate::operator_options::MLDimension::static_or_max(sz) as i32
                                * stride as i32
                    })
                    .collect();
                let ends_tensor = self.add_constant(
                    "slice_ends",
                    &[ends.len() as i32],
                    tflite::TensorType::INT32,
                    &ends
                        .iter()
                        .flat_map(|v| v.to_le_bytes())
                        .collect::<Vec<_>>(),
                );
                let stride_tensor = self.add_constant(
                    "slice_strides",
                    &[strides.len() as i32],
                    tflite::TensorType::INT32,
                    &strides
                        .iter()
                        .flat_map(|&s| (s as i32).to_le_bytes())
                        .collect::<Vec<_>>(),
                );
                let out_tensor =
                    *tensor_map.get(&op.outputs()[0]).unwrap_or(&op.outputs()[0]) as i32;
                let oc_idx = self.add_opcode(45, 1); // STRIDED_SLICE
                let iv = self.fbb.create_vector(&[
                    in_tensor,
                    begins_idx,
                    ends_tensor as i32,
                    stride_tensor as i32,
                ]);
                let ov = self.fbb.create_vector(&[out_tensor]);
                let sso = tflite::StridedSliceOptions::create(
                    &mut self.fbb,
                    &tflite::StridedSliceOptionsArgs {
                        begin_mask: 0,
                        end_mask: 0,
                        ellipsis_mask: 0,
                        new_axis_mask: 0,
                        shrink_axis_mask: 0,
                        offset: false,
                    },
                );
                let tfl_op = tflite::Operator::create(
                    &mut self.fbb,
                    &tflite::OperatorArgs {
                        opcode_index: oc_idx,
                        inputs: Some(iv),
                        outputs: Some(ov),
                        builtin_options: Some(sso.as_union_value()),
                        builtin_options_type: tflite::BuiltinOptions::StridedSliceOptions,
                        ..Default::default()
                    },
                );
                operator_offsets.push(tfl_op);
                return Some(true); // handled, skip normal path
            }
            let size_vals: Vec<i32> = sizes
                .iter()
                .map(|d| crate::operator_options::MLDimension::static_or_max(d) as i32)
                .collect();
            let sizes_tensor = self.add_constant(
                "slice_sizes",
                &[size_vals.len() as i32],
                tflite::TensorType::INT32,
                &size_vals
                    .iter()
                    .flat_map(|v| v.to_le_bytes())
                    .collect::<Vec<_>>(),
            );
            inputs.push(begins_idx);
            inputs.push(sizes_tensor as i32);
            return Some(false); // inputs added, continue normal path
        }
        None
    }

    /// Triangular: keep upper/lower triangle via constant mask + multiply.
    fn build_triangular_op(
        &mut self,
        op: &Operation,
        tensor_map: &mut HashMap<u32, u32>,
        operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
        in_tensor: i32,
        in_shape: &[i32],
        in_type: tflite::TensorType,
    ) -> bool {
        if let Operation::Triangular { options, .. } = op {
            if in_shape.len() < 2 {
                return false; // need at least 2D
            }
            let out_id = op.outputs()[0];
            let opts = options.as_ref().cloned().unwrap_or_default();
            let upper = opts.upper.unwrap_or(true);
            let diagonal = opts.diagonal;

            let rank = in_shape.len();
            let m = in_shape[rank - 2];
            let n = in_shape[rank - 1];
            let m_usize = m as usize;
            let n_usize = n as usize;

            // Row shape [1, ..., 1, M, 1] and Col shape [1, ..., 1, 1, N]
            let mut row_shape = vec![1i32; rank];
            row_shape[rank - 2] = m;
            row_shape[rank - 1] = 1;

            let mut col_shape = vec![1i32; rank];
            col_shape[rank - 2] = 1;
            col_shape[rank - 1] = n;

            // Row indices [0, 1, ..., M-1]
            let mut row_data = vec![0u8; m_usize * 4];
            for i in 0..m_usize {
                row_data[i * 4..(i + 1) * 4].copy_from_slice(&(i as i32).to_le_bytes());
            }
            let rows =
                self.add_constant("tri_rows", &row_shape, tflite::TensorType::INT32, &row_data);

            // Col indices [0, 1, ..., N-1]
            let mut col_data = vec![0u8; n_usize * 4];
            for j in 0..n_usize {
                col_data[j * 4..(j + 1) * 4].copy_from_slice(&(j as i32).to_le_bytes());
            }
            let cols =
                self.add_constant("tri_cols", &col_shape, tflite::TensorType::INT32, &col_data);

            // diagonal constant
            let diag_buf: Vec<u8> = diagonal.to_le_bytes().to_vec();
            let diag = self.add_constant("tri_diag", &[1], tflite::TensorType::INT32, &diag_buf);

            // row_index - diagonal, broadcast to row_shape
            let masked_rows = emit_op!(
                self,
                operator_offsets,
                std_op::SUB,
                [rows as i32, diag as i32],
                "tri_adj_rows",
                &row_shape,
                tflite::TensorType::INT32
            );

            // Comparison: broadcasts [M,1] with [1,N] → [M,N]
            let cmp_op = if upper {
                std_op::GREATER_EQUAL
            } else {
                std_op::LESS_EQUAL
            };
            // For upper: col >= row - diag
            // For lower: col <= row - diag
            let mask = emit_op!(
                self,
                operator_offsets,
                cmp_op,
                [cols as i32, masked_rows],
                "tri_mask",
                in_shape,
                tflite::TensorType::INT32
            );

            // Cast int32 mask to float via properly built CAST op
            let mask_f_tensor = self.add_tensor("tri_mask_f", in_shape, in_type, 0);
            let oc_cast = self.add_opcode(53, 1); // CAST opcode
            let iv_cast = self.fbb.create_vector(&[mask]);
            let ov_cast = self.fbb.create_vector(&[mask_f_tensor as i32]);
            let co = tflite::CastOptions::create(
                &mut self.fbb,
                &tflite::CastOptionsArgs {
                    in_data_type: tflite::TensorType::INT32,
                    out_data_type: in_type,
                },
            );
            operator_offsets.push(tflite::Operator::create(
                &mut self.fbb,
                &tflite::OperatorArgs {
                    opcode_index: oc_cast,
                    inputs: Some(iv_cast),
                    outputs: Some(ov_cast),
                    builtin_options: Some(co.as_union_value()),
                    builtin_options_type: tflite::BuiltinOptions::CastOptions,
                    ..Default::default()
                },
            ));
            let mask_f = mask_f_tensor as i32;

            let out = emit_op!(
                self,
                operator_offsets,
                std_op::MUL,
                [in_tensor, mask_f],
                "tri_out",
                in_shape,
                in_type
            );
            tensor_map.insert(out_id, out as u32);
            return true;
        }
        false
    }

    /// GatherElements: emulate with GATHER_ND + coordinate conversion.
    /// Chromium-style: only supports constant indices.
    fn build_gather_elements_op(
        &mut self,
        op: &Operation,
        graph: &GraphInfo,
        tensor_map: &mut HashMap<u32, u32>,
        operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
    ) -> bool {
        if let Operation::GatherElements {
            input,
            indices: indices_op_id,
            options,
            ..
        } = op
        {
            let out_id = op.outputs()[0];
            let axis = options.as_ref().map(|o| o.axis).unwrap_or(0) as usize;

            // Only constant indices supported (Chromium pattern)
            let indices_data = graph
                .constant_operand_ids_to_handles
                .get(indices_op_id)
                .map(|cd| cd.data.clone());
            let indices_data = match indices_data {
                Some(d) => d,
                None => return false,
            };

            // Get input shape and indices shape from operands
            let in_op = match graph.operand(*input) {
                Some(o) => o,
                None => return false,
            };
            let idx_op = match graph.operand(*indices_op_id) {
                Some(o) => o,
                None => return false,
            };
            let input_shape: Vec<i32> = in_op
                .descriptor
                .shape
                .iter()
                .map(|d| match d {
                    crate::graph::Dimension::Static(v) => *v as i32,
                    _ => 1,
                })
                .collect();
            let indices_shape: Vec<i32> = idx_op
                .descriptor
                .shape
                .iter()
                .map(|d| match d {
                    crate::graph::Dimension::Static(v) => *v as i32,
                    _ => 1,
                })
                .collect();
            let rank = indices_shape.len();
            let flat_size = indices_shape.iter().product::<i32>() as usize;

            // Parse int32 indices from raw bytes
            if indices_data.len() != flat_size * 4 {
                return false;
            }
            let indices_vals: Vec<i32> = indices_data
                .chunks(4)
                .map(|b| i32::from_le_bytes([b[0], b[1], b[2], b[3]]))
                .collect();

            // Clamp indices to [-N, N-1] range and handle negative
            let axis_dim = input_shape[axis];
            let clamped: Vec<i32> = indices_vals
                .iter()
                .map(|&v| {
                    let c = v.clamp(-axis_dim, axis_dim - 1);
                    if c < 0 { c + axis_dim } else { c }
                })
                .collect();

            // Compute strides for indices tensor
            let mut strides = vec![1i32; rank];
            for i in (0..rank - 1).rev() {
                strides[i] = strides[i + 1] * indices_shape[i + 1];
            }

            // Build coordinates: for each flat position, compute N-D coordinate
            // then replace coordinate[axis] with the clamped index value
            let coord_count = flat_size * rank;
            let mut coords: Vec<i32> = vec![0i32; coord_count];
            for flat_idx in 0..flat_size {
                // Compute N-D coordinate of this position in indices space
                let mut rem = flat_idx as i32;
                for d in 0..rank {
                    let coord = rem / strides[d];
                    rem -= coord * strides[d];
                    coords[flat_idx * rank + d] = coord;
                }
                // Replace coordinate at axis with the clamped index
                coords[flat_idx * rank + axis] = clamped[flat_idx];
            }

            // Create coordinates constant tensor [flat_size, input_rank]
            let coord_bytes: Vec<u8> = coords.iter().flat_map(|v| v.to_le_bytes()).collect();
            let coord_tensor = self.add_constant(
                "gather_e_coords",
                &[flat_size as i32, rank as i32],
                tflite::TensorType::INT32,
                &coord_bytes,
            );

            // Emit GATHER_ND with input + coordinates
            let in_tensor_idx = *tensor_map.get(input).unwrap_or(input) as i32;
            let gather_out_shape: Vec<i32> = vec![flat_size as i32];
            let gather_out = self.add_tensor(
                "gather_e_out",
                &gather_out_shape,
                tflite::TensorType::FLOAT32,
                0,
            );
            let oc_idx = self.add_opcode(std_op::GATHER_ND, 1);
            let iv = self
                .fbb
                .create_vector(&[in_tensor_idx, coord_tensor as i32]);
            let ov = self.fbb.create_vector(&[gather_out as i32]);
            operator_offsets.push(tflite::Operator::create(
                &mut self.fbb,
                &tflite::OperatorArgs {
                    opcode_index: oc_idx,
                    inputs: Some(iv),
                    outputs: Some(ov),
                    ..Default::default()
                },
            ));

            // Reshape gather_out to indices_shape
            let out_tensor = *tensor_map.get(&out_id).unwrap_or(&out_id) as i32;
            let shape_bytes: Vec<u8> = indices_shape.iter().flat_map(|v| v.to_le_bytes()).collect();
            let shape_const = self.add_constant(
                "gather_e_shape",
                &[indices_shape.len() as i32],
                tflite::TensorType::INT32,
                &shape_bytes,
            );
            let oc_reshape = self.add_opcode(std_op::RESHAPE, 1);
            let iv_r = self
                .fbb
                .create_vector(&[gather_out as i32, shape_const as i32]);
            let ov_r = self.fbb.create_vector(&[out_tensor]);
            let shape_vec = self.fbb.create_vector(&indices_shape);
            let ro = tflite::ReshapeOptions::create(
                &mut self.fbb,
                &tflite::ReshapeOptionsArgs {
                    new_shape: Some(shape_vec),
                },
            );
            operator_offsets.push(tflite::Operator::create(
                &mut self.fbb,
                &tflite::OperatorArgs {
                    opcode_index: oc_reshape,
                    inputs: Some(iv_r),
                    outputs: Some(ov_r),
                    builtin_options: Some(ro.as_union_value()),
                    builtin_options_type: tflite::BuiltinOptions::ReshapeOptions,
                    ..Default::default()
                },
            ));
            tensor_map.insert(out_id, out_tensor as u32);
            return true;
        }
        false
    }

    /// ScatterElements: emulate with SCATTER_ND + coordinate conversion.
    /// Chromium-style: only supports constant int32 indices.
    fn build_scatter_elements_op(
        &mut self,
        op: &Operation,
        graph: &GraphInfo,
        tensor_map: &mut HashMap<u32, u32>,
        operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
    ) -> bool {
        if let Operation::ScatterElements {
            input,
            indices: indices_op_id,
            updates: updates_op_id,
            options,
            ..
        } = op
        {
            let out_id = op.outputs()[0];
            let axis = options.as_ref().map(|o| o.axis).unwrap_or(0) as usize;

            let indices_data = graph
                .constant_operand_ids_to_handles
                .get(indices_op_id)
                .map(|cd| cd.data.clone());
            let indices_data = match indices_data {
                Some(d) => d,
                None => return false,
            };

            let in_op = match graph.operand(*input) {
                Some(o) => o,
                None => return false,
            };
            let idx_op = match graph.operand(*indices_op_id) {
                Some(o) => o,
                None => return false,
            };
            let input_shape: Vec<i32> = in_op
                .descriptor
                .shape
                .iter()
                .map(|d| match d {
                    crate::graph::Dimension::Static(v) => *v as i32,
                    _ => 1,
                })
                .collect();
            let indices_shape: Vec<i32> = idx_op
                .descriptor
                .shape
                .iter()
                .map(|d| match d {
                    crate::graph::Dimension::Static(v) => *v as i32,
                    _ => 1,
                })
                .collect();
            let rank = indices_shape.len();
            let flat_size = indices_shape.iter().product::<i32>() as usize;

            if indices_data.len() != flat_size * 4 {
                return false;
            }
            let indices_vals: Vec<i32> = indices_data
                .chunks(4)
                .map(|b| i32::from_le_bytes([b[0], b[1], b[2], b[3]]))
                .collect();

            let axis_dim = input_shape[axis];
            let clamped: Vec<i32> = indices_vals
                .iter()
                .map(|&v| {
                    let c = v.clamp(-axis_dim, axis_dim - 1);
                    if c < 0 { c + axis_dim } else { c }
                })
                .collect();

            let mut strides = vec![1i32; rank];
            for i in (0..rank - 1).rev() {
                strides[i] = strides[i + 1] * indices_shape[i + 1];
            }

            let coord_count = flat_size * rank;
            let mut coords: Vec<i32> = vec![0i32; coord_count];
            for flat_idx in 0..flat_size {
                let mut rem = flat_idx as i32;
                for d in 0..rank {
                    let coord = rem / strides[d];
                    rem -= coord * strides[d];
                    coords[flat_idx * rank + d] = coord;
                }
                coords[flat_idx * rank + axis] = clamped[flat_idx];
            }

            let coord_bytes: Vec<u8> = coords.iter().flat_map(|v| v.to_le_bytes()).collect();
            let coord_tensor = self.add_constant(
                "scatter_e_coords",
                &[flat_size as i32, rank as i32],
                tflite::TensorType::INT32,
                &coord_bytes,
            );

            // Get input data type for scatter tensors
            let in_type = graph
                .operand(*input)
                .and_then(|o| datatype_to_tflite(o.descriptor.data_type).ok())
                .unwrap_or(tflite::TensorType::FLOAT32);

            // Reshape updates to 1D [flat_size]
            let updates_tensor = *tensor_map.get(updates_op_id).unwrap_or(updates_op_id) as i32;
            let updates_1d_tensor =
                self.add_tensor("scatter_e_upd", &[flat_size as i32], in_type, 0);
            let shape_bytes: Vec<u8> = (flat_size as i32).to_le_bytes().to_vec();
            let shape_const = self.add_constant(
                "scatter_e_reshape",
                &[1],
                tflite::TensorType::INT32,
                &shape_bytes,
            );
            let oc_r = self.add_opcode(std_op::RESHAPE, 1);
            let iv_r = self
                .fbb
                .create_vector(&[updates_tensor, shape_const as i32]);
            let ov_r = self.fbb.create_vector(&[updates_1d_tensor as i32]);
            let shape_vec = self.fbb.create_vector(&[flat_size as i32]);
            let ro = tflite::ReshapeOptions::create(
                &mut self.fbb,
                &tflite::ReshapeOptionsArgs {
                    new_shape: Some(shape_vec),
                },
            );
            operator_offsets.push(tflite::Operator::create(
                &mut self.fbb,
                &tflite::OperatorArgs {
                    opcode_index: oc_r,
                    inputs: Some(iv_r),
                    outputs: Some(ov_r),
                    builtin_options: Some(ro.as_union_value()),
                    builtin_options_type: tflite::BuiltinOptions::ReshapeOptions,
                    ..Default::default()
                },
            ));

            // TFLite SCATTER_ND expects: (indices, updates, input_shape).
            // SCATTER_ND internally creates the output tensor from the shape
            // and initializes it to zeros, so no zero-input tensor is needed.
            let input_shape_bytes: Vec<u8> =
                input_shape.iter().flat_map(|v| v.to_le_bytes()).collect();
            let input_shape_tensor = self.add_constant(
                "scatter_e_shape",
                &[input_shape.len() as i32],
                tflite::TensorType::INT32,
                &input_shape_bytes,
            );

            // Pass 1: SCATTER_ND with BOOL true values → position mask
            let true_data: Vec<u8> = std::iter::repeat(1u8).take(flat_size).collect();
            let true_updates = self.add_constant(
                "scatter_true_upd",
                &[flat_size as i32],
                tflite::TensorType::BOOL,
                &true_data,
            );
            let mask_out = self.add_tensor(
                "scatter_mask_out",
                &input_shape,
                tflite::TensorType::BOOL,
                0,
            );
            let oc_s1 = self.add_opcode(std_op::SCATTER_ND, 1);
            let iv_s1 = self.fbb.create_vector(&[
                coord_tensor as i32,
                true_updates as i32,
                input_shape_tensor as i32,
            ]);
            let ov_s1 = self.fbb.create_vector(&[mask_out as i32]);
            operator_offsets.push(tflite::Operator::create(
                &mut self.fbb,
                &tflite::OperatorArgs {
                    opcode_index: oc_s1,
                    inputs: Some(iv_s1),
                    outputs: Some(ov_s1),
                    ..Default::default()
                },
            ));

            // Pass 2: SCATTER_ND with actual update values
            let values_out = self.add_tensor("scatter_val_out", &input_shape, in_type, 0);
            let oc_s2 = self.add_opcode(std_op::SCATTER_ND, 1);
            let iv_s2 = self.fbb.create_vector(&[
                coord_tensor as i32,
                updates_1d_tensor as i32,
                input_shape_tensor as i32,
            ]);
            let ov_s2 = self.fbb.create_vector(&[values_out as i32]);
            operator_offsets.push(tflite::Operator::create(
                &mut self.fbb,
                &tflite::OperatorArgs {
                    opcode_index: oc_s2,
                    inputs: Some(iv_s2),
                    outputs: Some(ov_s2),
                    ..Default::default()
                },
            ));

            // Pass 3: WHERE(mask, scattered_values, original_input) → output
            let in_tensor = *tensor_map.get(input).unwrap_or(input) as i32;
            let out_tensor_idx = *tensor_map.get(&out_id).unwrap_or(&out_id) as i32;
            let oc_w = self.add_opcode(std_op::SELECT, 1);
            let iv_w = self
                .fbb
                .create_vector(&[mask_out as i32, values_out as i32, in_tensor]);
            let ov_w = self.fbb.create_vector(&[out_tensor_idx]);
            operator_offsets.push(tflite::Operator::create(
                &mut self.fbb,
                &tflite::OperatorArgs {
                    opcode_index: oc_w,
                    inputs: Some(iv_w),
                    outputs: Some(ov_w),
                    ..Default::default()
                },
            ));
            tensor_map.insert(out_id, out_tensor_idx as u32);
            return true;
        }
        false
    }

    /// ScatterND: emulate with SCATTER_ND + WHERE (same pattern as Chromium's WebNNScatterND).
    /// Only supports constant int32 indices with positive values (no negative clamping for now).
    fn build_scatter_nd_op(
        &mut self,
        op: &Operation,
        graph: &GraphInfo,
        tensor_map: &mut HashMap<u32, u32>,
        operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
    ) -> bool {
        if let Operation::ScatterND {
            input,
            indices: indices_op_id,
            updates: updates_op_id,
            ..
        } = op
        {
            let out_id = op.outputs()[0];

            let in_op = match graph.operand(*input) {
                Some(o) => o,
                None => return false,
            };
            let idx_op = match graph.operand(*indices_op_id) {
                Some(o) => o,
                None => return false,
            };
            let upd_op = match graph.operand(*updates_op_id) {
                Some(o) => o,
                None => return false,
            };

            let input_shape: Vec<i32> = in_op
                .descriptor
                .shape
                .iter()
                .map(|d| match d {
                    crate::graph::Dimension::Static(v) => *v as i32,
                    _ => 1,
                })
                .collect();
            let updates_shape: Vec<i32> = upd_op
                .descriptor
                .shape
                .iter()
                .map(|d| match d {
                    crate::graph::Dimension::Static(v) => *v as i32,
                    _ => 1,
                })
                .collect();
            let indices_shape: Vec<i32> = idx_op
                .descriptor
                .shape
                .iter()
                .map(|d| match d {
                    crate::graph::Dimension::Static(v) => *v as i32,
                    _ => 1,
                })
                .collect();

            if indices_shape.len() < 2 {
                return false;
            }

            let in_type = datatype_to_tflite(in_op.descriptor.data_type)
                .unwrap_or(tflite::TensorType::FLOAT32);

            // Only support constant indices for now (like ScatterElements)
            let indices_data = graph
                .constant_operand_ids_to_handles
                .get(indices_op_id)
                .map(|cd| cd.data.clone());
            let indices_data = match indices_data {
                Some(d) => d,
                None => return false,
            };

            let num_updates = indices_shape[0] as usize;
            let indexing_depth = indices_shape[1] as usize;
            let expected_len = num_updates * indexing_depth * 4;
            if indices_data.len() < expected_len {
                return false;
            }

            // Parse indices and clamp negative values
            let indices_vals: Vec<i32> = indices_data[..expected_len]
                .chunks(4)
                .map(|b| i32::from_le_bytes([b[0], b[1], b[2], b[3]]))
                .collect();
            let clamped: Vec<i32> = indices_vals
                .chunks(indexing_depth)
                .flat_map(|coord| {
                    coord.iter().enumerate().map(|(d, &v)| {
                        let dim_size = input_shape.get(d).copied().unwrap_or(1);
                        let c = v.clamp(-dim_size, dim_size - 1);
                        if c < 0 { c + dim_size } else { c }
                    })
                })
                .collect();

            let coord_bytes: Vec<u8> = clamped.iter().flat_map(|v| v.to_le_bytes()).collect();
            let indices_tensor = self.add_constant(
                "scatternd_indices",
                &indices_shape,
                tflite::TensorType::INT32,
                &coord_bytes,
            );

            // Input shape as constant 1D tensor
            let input_shape_bytes: Vec<u8> =
                input_shape.iter().flat_map(|v| v.to_le_bytes()).collect();
            let input_shape_tensor = self.add_constant(
                "scatternd_shape",
                &[input_shape.len() as i32],
                tflite::TensorType::INT32,
                &input_shape_bytes,
            );

            // Pass 1: SCATTER_ND with BOOL true values → position mask
            let num_upd_elements: usize = updates_shape.iter().product::<i32>() as usize;
            let true_data: Vec<u8> = std::iter::repeat(1u8).take(num_upd_elements).collect();
            let true_updates = self.add_constant(
                "scatternd_true_upd",
                &updates_shape,
                tflite::TensorType::BOOL,
                &true_data,
            );
            let mask_out = self.add_tensor(
                "scatternd_mask_out",
                &input_shape,
                tflite::TensorType::BOOL,
                0,
            );
            let oc_s1 = self.add_opcode(std_op::SCATTER_ND, 1);
            let iv_s1 = self.fbb.create_vector(&[
                indices_tensor as i32,
                true_updates as i32,
                input_shape_tensor as i32,
            ]);
            let ov_s1 = self.fbb.create_vector(&[mask_out as i32]);
            operator_offsets.push(tflite::Operator::create(
                &mut self.fbb,
                &tflite::OperatorArgs {
                    opcode_index: oc_s1,
                    inputs: Some(iv_s1),
                    outputs: Some(ov_s1),
                    ..Default::default()
                },
            ));

            // Pass 2: SCATTER_ND with actual update values
            let updates_tensor = *tensor_map.get(updates_op_id).unwrap_or(updates_op_id) as i32;
            let values_out = self.add_tensor("scatternd_val_out", &input_shape, in_type, 0);
            let oc_s2 = self.add_opcode(std_op::SCATTER_ND, 1);
            let iv_s2 = self.fbb.create_vector(&[
                indices_tensor as i32,
                updates_tensor,
                input_shape_tensor as i32,
            ]);
            let ov_s2 = self.fbb.create_vector(&[values_out as i32]);
            operator_offsets.push(tflite::Operator::create(
                &mut self.fbb,
                &tflite::OperatorArgs {
                    opcode_index: oc_s2,
                    inputs: Some(iv_s2),
                    outputs: Some(ov_s2),
                    ..Default::default()
                },
            ));

            // Pass 3: WHERE(mask, scattered_values, original_input) → output
            let in_tensor = *tensor_map.get(input).unwrap_or(input) as i32;
            let out_tensor_idx = *tensor_map.get(&out_id).unwrap_or(&out_id) as i32;
            let oc_w = self.add_opcode(std_op::SELECT, 1);
            let iv_w = self
                .fbb
                .create_vector(&[mask_out as i32, values_out as i32, in_tensor]);
            let ov_w = self.fbb.create_vector(&[out_tensor_idx]);
            operator_offsets.push(tflite::Operator::create(
                &mut self.fbb,
                &tflite::OperatorArgs {
                    opcode_index: oc_w,
                    inputs: Some(iv_w),
                    outputs: Some(ov_w),
                    ..Default::default()
                },
            ));
            tensor_map.insert(out_id, out_tensor_idx as u32);
            return true;
        }
        false
    }

    /// ConvTranspose2d: reorder inputs to TFLite format [output_shape, filter, input, bias].
    fn build_conv_transpose_op(
        &mut self,
        op: &Operation,
        graph: &GraphInfo,
        tensor_map: &HashMap<u32, u32>,
        inputs: &mut Vec<i32>,
    ) -> bool {
        if let Operation::ConvTranspose2d { .. } = op {
            let input_ids = op.inputs();
            if input_ids.len() < 2 {
                return false;
            }
            let out_id = op.outputs()[0];

            // Output shape tensor from output operand
            let out_shape: Vec<i32> = graph
                .operand(out_id)
                .map(|o| {
                    o.descriptor
                        .shape
                        .iter()
                        .map(|d| match d {
                            crate::graph::Dimension::Static(v) => *v as i32,
                            _ => 1,
                        })
                        .collect()
                })
                .unwrap_or_default();

            let shape_bytes: Vec<u8> = out_shape.iter().flat_map(|v| v.to_le_bytes()).collect();
            let output_shape_tensor = self.add_constant(
                "conv_transpose_shape",
                &[out_shape.len() as i32],
                tflite::TensorType::INT32,
                &shape_bytes,
            );

            // Add zero bias
            let filter_id = input_ids[1];
            let oc = graph
                .operand(filter_id)
                .and_then(|o| {
                    o.descriptor
                        .shape
                        .iter()
                        .rev()
                        .nth(2)
                        .and_then(|d| match d {
                            crate::graph::Dimension::Static(v) => Some(*v as i32),
                            _ => None,
                        })
                })
                .unwrap_or(1);
            let in_type = graph
                .operand(input_ids[0])
                .map(|o| {
                    datatype_to_tflite(o.descriptor.data_type)
                        .unwrap_or(tflite::TensorType::FLOAT32)
                })
                .unwrap_or(tflite::TensorType::FLOAT32);
            let esz = 4;
            let bias = self.add_constant(
                "conv_transpose_bias",
                &[oc],
                in_type,
                &vec![0u8; oc as usize * esz],
            );

            // Reorder: [output_shape, filter, input, bias]
            let filter_tensor = *tensor_map.get(&filter_id).unwrap_or(&filter_id) as i32;
            let input_tensor = *tensor_map.get(&input_ids[0]).unwrap_or(&input_ids[0]) as i32;
            *inputs = vec![
                output_shape_tensor as i32,
                filter_tensor,
                input_tensor,
                bias as i32,
            ];
            return true;
        }
        false
    }

    /// Split: use SPLIT_V with input, split_sizes, and axis tensors.
    fn build_split_op(
        &mut self,
        op: &Operation,
        graph: &GraphInfo,
        tensor_map: &HashMap<u32, u32>,
        inputs: &mut Vec<i32>,
    ) -> bool {
        if let Operation::Split { options, .. } = op {
            let opts = options.as_ref().cloned().unwrap_or_default();
            let axis = opts.axis as i32;
            let input_id = op.inputs()[0];
            let in_tensor = *tensor_map.get(&input_id).unwrap_or(&input_id) as i32;
            let output_ids = op.outputs();

            // Build split sizes: each output's size along the split axis
            let num_splits = output_ids.len();
            let mut split_sizes = Vec::with_capacity(num_splits);
            for &out_id in output_ids {
                let size = graph
                    .operand(out_id)
                    .and_then(|o| o.descriptor.shape.get(axis as usize))
                    .and_then(|d| match d {
                        crate::graph::Dimension::Static(v) => Some(*v as i32),
                        _ => None,
                    })
                    .unwrap_or(1);
                split_sizes.push(size);
            }

            let sizes_bytes: Vec<u8> = split_sizes.iter().flat_map(|v| v.to_le_bytes()).collect();
            let sizes_tensor = self.add_constant(
                "split_sizes",
                &[num_splits as i32],
                tflite::TensorType::INT32,
                &sizes_bytes,
            );

            let axis_bytes = axis.to_le_bytes();
            let axis_tensor =
                self.add_constant("split_axis", &[1], tflite::TensorType::INT32, &axis_bytes);

            // SPLIT_V inputs: [input, split_sizes, axis]
            *inputs = vec![in_tensor, sizes_tensor as i32, axis_tensor as i32];
            return true;
        }
        false
    }

    fn create_builtin_options(
        &mut self,
        op: &Operation,
        graph: &GraphInfo,
        input_id: u32,
    ) -> Result<
        (
            Option<WIPOffset<flatbuffers::UnionWIPOffset>>,
            tflite::BuiltinOptions,
        ),
        GraphError,
    > {
        let result = match op {
            Operation::Conv2d { options, .. } => {
                let o = options.as_ref().cloned().unwrap_or_default();
                let (sh, sw) = if o.strides.len() >= 2 {
                    (o.strides[0] as i32, o.strides[1] as i32)
                } else {
                    (1, 1)
                };
                let (dh, dw) = if o.dilations.len() >= 2 {
                    (o.dilations[0] as i32, o.dilations[1] as i32)
                } else {
                    (1, 1)
                };
                let co = tflite::Conv2DOptions::create(
                    &mut self.fbb,
                    &tflite::Conv2DOptionsArgs {
                        padding: tflite::Padding::VALID,
                        stride_w: sw,
                        stride_h: sh,
                        fused_activation_function: tflite::ActivationFunctionType::NONE,
                        dilation_w_factor: dw,
                        dilation_h_factor: dh,
                        ..Default::default()
                    },
                );
                (
                    Some(co.as_union_value()),
                    tflite::BuiltinOptions::Conv2DOptions,
                )
            }
            Operation::ConvTranspose2d { options, .. } => {
                let o = options.as_ref().cloned().unwrap_or_default();
                let (sh, sw) = if o.strides.len() >= 2 {
                    (o.strides[0] as i32, o.strides[1] as i32)
                } else {
                    (1, 1)
                };
                let to = tflite::TransposeConvOptions::create(
                    &mut self.fbb,
                    &tflite::TransposeConvOptionsArgs {
                        padding: tflite::Padding::VALID,
                        stride_w: sw,
                        stride_h: sh,
                        fused_activation_function: tflite::ActivationFunctionType::NONE,
                        ..Default::default()
                    },
                );
                (
                    Some(to.as_union_value()),
                    tflite::BuiltinOptions::TransposeConvOptions,
                )
            }
            Operation::MaxPool2d { options, .. } | Operation::AveragePool2d { options, .. } => {
                let o = options.as_ref().cloned().unwrap_or_default();
                let (sh, sw) = if o.strides.len() >= 2 {
                    (o.strides[0] as i32, o.strides[1] as i32)
                } else {
                    (1, 1)
                };
                let (fh, fw) = if let Some(wd) = &o.window_dimensions {
                    if wd.len() >= 2 {
                        (wd[0] as i32, wd[1] as i32)
                    } else {
                        (0, 0)
                    }
                } else {
                    (0, 0)
                };
                let po = tflite::Pool2DOptions::create(
                    &mut self.fbb,
                    &tflite::Pool2DOptionsArgs {
                        padding: tflite::Padding::VALID,
                        stride_w: sw,
                        stride_h: sh,
                        filter_width: fw,
                        filter_height: fh,
                        fused_activation_function: tflite::ActivationFunctionType::NONE,
                    },
                );
                (
                    Some(po.as_union_value()),
                    tflite::BuiltinOptions::Pool2DOptions,
                )
            }
            Operation::Reshape { new_shape, .. } => {
                let shape_vec = self.fbb.create_vector(
                    &new_shape
                        .iter()
                        .map(|d| crate::operator_options::MLDimension::static_or_max(d) as i32)
                        .collect::<Vec<i32>>(),
                );
                let ro = tflite::ReshapeOptions::create(
                    &mut self.fbb,
                    &tflite::ReshapeOptionsArgs {
                        new_shape: Some(shape_vec),
                    },
                );
                (
                    Some(ro.as_union_value()),
                    tflite::BuiltinOptions::ReshapeOptions,
                )
            }
            Operation::ReduceSum { options, .. }
            | Operation::ReduceMean { options, .. }
            | Operation::ReduceMax { options, .. }
            | Operation::ReduceMin { options, .. }
            | Operation::ReduceProduct { options, .. } => {
                let keep_dims = options.as_ref().map(|o| o.keep_dimensions).unwrap_or(true);
                let ro = tflite::ReducerOptions::create(
                    &mut self.fbb,
                    &tflite::ReducerOptionsArgs { keep_dims },
                );
                (
                    Some(ro.as_union_value()),
                    tflite::BuiltinOptions::ReducerOptions,
                )
            }
            Operation::Concat { axis, .. } => {
                let co = tflite::ConcatenationOptions::create(
                    &mut self.fbb,
                    &tflite::ConcatenationOptionsArgs {
                        axis: *axis as i32,
                        fused_activation_function: tflite::ActivationFunctionType::NONE,
                    },
                );
                (
                    Some(co.as_union_value()),
                    tflite::BuiltinOptions::ConcatenationOptions,
                )
            }
            Operation::LeakyRelu { options, .. } => {
                let alpha = options.as_ref().map(|o| o.alpha as f32).unwrap_or(0.01);
                let lo = tflite::LeakyReluOptions::create(
                    &mut self.fbb,
                    &tflite::LeakyReluOptionsArgs { alpha },
                );
                (
                    Some(lo.as_union_value()),
                    tflite::BuiltinOptions::LeakyReluOptions,
                )
            }
            Operation::Gather { options, .. } => {
                let axis = options.as_ref().map(|o| o.axis as i32).unwrap_or(0);
                let go = tflite::GatherOptions::create(
                    &mut self.fbb,
                    &tflite::GatherOptionsArgs {
                        axis,
                        batch_dims: 0,
                    },
                );
                (
                    Some(go.as_union_value()),
                    tflite::BuiltinOptions::GatherOptions,
                )
            }
            Operation::ArgMax { options, .. } | Operation::ArgMin { options, .. } => {
                let out_dt = options
                    .as_ref()
                    .map(|o| match o.output_data_type {
                        crate::operator_enums::MLOperandDataType::Int32 => {
                            tflite::TensorType::INT32
                        }
                        crate::operator_enums::MLOperandDataType::Int64 => {
                            tflite::TensorType::INT64
                        }
                        _ => tflite::TensorType::INT32,
                    })
                    .unwrap_or(tflite::TensorType::INT32);
                if matches!(op, Operation::ArgMax { .. }) {
                    let ao = tflite::ArgMaxOptions::create(
                        &mut self.fbb,
                        &tflite::ArgMaxOptionsArgs {
                            output_type: out_dt,
                        },
                    );
                    (
                        Some(ao.as_union_value()),
                        tflite::BuiltinOptions::ArgMaxOptions,
                    )
                } else {
                    let ao = tflite::ArgMinOptions::create(
                        &mut self.fbb,
                        &tflite::ArgMinOptionsArgs {
                            output_type: out_dt,
                        },
                    );
                    (
                        Some(ao.as_union_value()),
                        tflite::BuiltinOptions::ArgMinOptions,
                    )
                }
            }
            Operation::CumulativeSum { options, .. } => {
                let opts = options.as_ref().cloned().unwrap_or_default();
                let co = tflite::CumsumOptions::create(
                    &mut self.fbb,
                    &tflite::CumsumOptionsArgs {
                        exclusive: opts.exclusive,
                        reverse: opts.reversed,
                    },
                );
                (
                    Some(co.as_union_value()),
                    tflite::BuiltinOptions::CumsumOptions,
                )
            }
            Operation::Resample2d { .. } => {
                let ro = tflite::ResizeBilinearOptions::create(
                    &mut self.fbb,
                    &tflite::ResizeBilinearOptionsArgs {
                        align_corners: false,
                        half_pixel_centers: false,
                    },
                );
                (
                    Some(ro.as_union_value()),
                    tflite::BuiltinOptions::ResizeBilinearOptions,
                )
            }
            Operation::Cast { data_type, .. } => {
                let out_dt = datatype_to_tflite(crate::graph::DataType::from(*data_type))?;
                let in_dt = graph
                    .operand(input_id)
                    .map(|o| datatype_to_tflite(o.descriptor.data_type).expect("unsupported dtype"))
                    .unwrap_or(tflite::TensorType::FLOAT32);
                let co = tflite::CastOptions::create(
                    &mut self.fbb,
                    &tflite::CastOptionsArgs {
                        in_data_type: in_dt,
                        out_data_type: out_dt,
                    },
                );
                (
                    Some(co.as_union_value()),
                    tflite::BuiltinOptions::CastOptions,
                )
            }
            Operation::Softmax { .. } => {
                let so = tflite::SoftmaxOptions::create(
                    &mut self.fbb,
                    &tflite::SoftmaxOptionsArgs { beta: 1.0 },
                );
                (
                    Some(so.as_union_value()),
                    tflite::BuiltinOptions::SoftmaxOptions,
                )
            }
            Operation::Squeeze { options, .. } => {
                let axes: Vec<i32> = if let Some(opts) = options {
                    opts.axes.iter().map(|&v| v as i32).collect()
                } else {
                    vec![]
                };
                let axes_vec = self.fbb.create_vector(&axes);
                let so = tflite::SqueezeOptions::create(
                    &mut self.fbb,
                    &tflite::SqueezeOptionsArgs {
                        squeeze_dims: Some(axes_vec),
                    },
                );
                (
                    Some(so.as_union_value()),
                    tflite::BuiltinOptions::SqueezeOptions,
                )
            }
            Operation::Split { .. } => {
                let num_splits = op.outputs().len() as i32;
                let so = tflite::SplitVOptions::create(
                    &mut self.fbb,
                    &tflite::SplitVOptionsArgs { num_splits },
                );
                (
                    Some(so.as_union_value()),
                    tflite::BuiltinOptions::SplitVOptions,
                )
            }
            _ => (None, tflite::BuiltinOptions::NONE),
        };
        Ok(result)
    }
}

fn build_spatial_inputs<'a>(
    ctx: &mut TfliteContext<'a>,
    op: &Operation,
    graph: &GraphInfo,
    inputs: &mut Vec<i32>,
    in_tensor: i32,
    in_type: tflite::TensorType,
    operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
) -> Result<(), GraphError> {
    // TFLite Conv2D requires a bias tensor (3rd input). Add zero bias if missing.
    if let Operation::Conv2d { options, .. } = op {
        let input_ids = op.inputs();
        if options.as_ref().and_then(|o| o.bias).is_none() && input_ids.len() >= 2 {
            if let Some(fop) = graph.operand(input_ids[1]) {
                let oc = fop
                    .descriptor
                    .shape
                    .first()
                    .and_then(|d| {
                        if let crate::graph::Dimension::Static(v) = d {
                            Some(*v as i32)
                        } else {
                            None
                        }
                    })
                    .unwrap_or(1);
                let tt = datatype_to_tflite(fop.descriptor.data_type)?;
                let esz = 4;
                inputs.push(
                    ctx.add_constant("bias", &[oc], tt, &vec![0u8; oc as usize * esz]) as i32,
                );
            }
        }
    }

    // TFLite ConvTranspose2d always requires a bias tensor. Add zero bias.
    if let Operation::ConvTranspose2d { .. } = op {
        let input_ids = op.inputs();
        if input_ids.len() >= 2 {
            if let Some(fop) = graph.operand(input_ids[1]) {
                let oc = fop
                    .descriptor
                    .shape
                    .first()
                    .and_then(|d| {
                        if let crate::graph::Dimension::Static(v) = d {
                            Some(*v as i32)
                        } else {
                            None
                        }
                    })
                    .unwrap_or(1);
                let tt = datatype_to_tflite(fop.descriptor.data_type)?;
                let esz = 4;
                inputs.push(
                    ctx.add_constant("bias", &[oc], tt, &vec![0u8; oc as usize * esz]) as i32,
                );
            }
        }
    }

    // Handle explicit padding for Conv2d/Pool2d by inserting a PAD op before it.
    let pad_opts: Option<(Vec<u32>, bool)> = match op {
        Operation::Conv2d { options, .. } => options.as_ref().map(|o| (o.padding.clone(), false)),
        Operation::MaxPool2d { options, .. } | Operation::AveragePool2d { options, .. } => {
            options.as_ref().map(|o| (o.padding.clone(), true))
        }
        _ => None,
    };
    if let Some((padding, _is_pool)) = pad_opts {
        if padding.len() >= 4 {
            let ph0 = padding[0] as i32;
            let pw0 = padding[1] as i32;
            let ph1 = padding[2] as i32;
            let pw1 = padding[3] as i32;
            let pad_vals: [i32; 8] = [0, 0, ph0, ph1, pw0, pw1, 0, 0];
            let pad_buf: Vec<u8> = pad_vals.iter().flat_map(|v| v.to_le_bytes()).collect();
            let pad_tensor = ctx.add_constant(
                "conv2d_prepad",
                &[4, 2],
                tflite::TensorType::INT32,
                &pad_buf,
            );
            let in_shape = &graph
                .operand(op.inputs()[0])
                .map(|op_info| {
                    op_info
                        .descriptor
                        .shape
                        .iter()
                        .map(|d| match d {
                            crate::graph::Dimension::Static(v) => *v as i32,
                            _ => 1,
                        })
                        .collect::<Vec<_>>()
                })
                .unwrap_or(vec![1, 1, 1, 1]);
            if in_shape.len() == 4 {
                let padded_shape = vec![
                    in_shape[0],
                    in_shape[1] + ph0 + ph1,
                    in_shape[2] + pw0 + pw1,
                    in_shape[3],
                ];
                let padded_tensor = ctx.add_tensor("conv2d_padded", &padded_shape, in_type, 0);
                let pad_oc = ctx.add_opcode(std_op::PAD, 1);
                let pad_iv = ctx.fbb.create_vector(&[in_tensor, pad_tensor as i32]);
                let pad_ov = ctx.fbb.create_vector(&[padded_tensor as i32]);
                let pad_op = tflite::Operator::create(
                    &mut ctx.fbb,
                    &tflite::OperatorArgs {
                        opcode_index: pad_oc,
                        inputs: Some(pad_iv),
                        outputs: Some(pad_ov),
                        builtin_options: None,
                        builtin_options_type: tflite::BuiltinOptions::NONE,
                        ..Default::default()
                    },
                );
                operator_offsets.push(pad_op);
                inputs[0] = padded_tensor as i32;
            }
        }
    }
    Ok(())
}

/// Add axes input for reduce ops. Returns Ok(true) if op was handled (empty axes = identity).
fn build_reduce_inputs(
    ctx: &mut TfliteContext<'_>,
    op: &Operation,
    tensor_map: &mut HashMap<u32, u32>,
    input_id: u32,
    in_shape: &[i32],
    inputs: &mut Vec<i32>,
) -> Result<bool, GraphError> {
    let is_reduce = matches!(
        op,
        Operation::ReduceSum { .. }
            | Operation::ReduceMean { .. }
            | Operation::ReduceMax { .. }
            | Operation::ReduceMin { .. }
            | Operation::ReduceProduct { .. }
    );
    if !is_reduce {
        return Ok(false);
    }
    let axes_opt: Option<Vec<u32>> = match op {
        Operation::ReduceSum { options, .. }
        | Operation::ReduceMean { options, .. }
        | Operation::ReduceMax { options, .. }
        | Operation::ReduceMin { options, .. }
        | Operation::ReduceProduct { options, .. } => options.as_ref().and_then(|o| o.axes.clone()),
        _ => None,
    };
    let axes: Vec<i32> = match axes_opt {
        Some(ref a) if !a.is_empty() => a.iter().map(|&v| v as i32).collect(),
        Some(ref a) if a.is_empty() => vec![],
        None => (0..in_shape.len() as i32).collect(),
        _ => (0..in_shape.len() as i32).collect(),
    };
    if axes.is_empty() {
        let input_tensor = *tensor_map.get(&input_id).unwrap_or(&input_id);
        for &out_id in op.outputs() {
            tensor_map.insert(out_id, input_tensor);
        }
        return Ok(true); // skip this op
    }
    let axes_bytes: Vec<u8> = axes.iter().flat_map(|v| v.to_le_bytes()).collect();
    let ax_tensor = ctx.add_constant(
        "reduce_axes",
        &[axes.len() as i32],
        tflite::TensorType::INT32,
        &axes_bytes,
    );
    inputs.push(ax_tensor as i32);
    Ok(false)
}

/// Add extra input tensors for shape ops. Returns Ok(true) if op fully handled.
fn build_extra_inputs<'a>(
    ctx: &mut TfliteContext<'a>,
    op: &Operation,
    in_shape: &[i32],
    in_tensor: i32,
    inputs: &mut Vec<i32>,
    tensor_map: &HashMap<u32, u32>,
    operator_offsets: &mut Vec<WIPOffset<tflite::Operator<'a>>>,
) -> Result<bool, GraphError> {
    // Expand: add shape tensor as input[1]
    if let Operation::Expand { new_shape, .. } = op {
        let shape_vals: Vec<i32> = new_shape
            .iter()
            .map(|d| crate::operator_options::MLDimension::static_or_max(d) as i32)
            .collect();
        let shape_bytes: Vec<u8> = shape_vals.iter().flat_map(|v| v.to_le_bytes()).collect();
        let shape_tensor = ctx.add_constant(
            "expand_shape",
            &[shape_vals.len() as i32],
            tflite::TensorType::INT32,
            &shape_bytes,
        );
        inputs.push(shape_tensor as i32);
        return Ok(false);
    }

    // Transpose: add perm tensor as input[1]
    if let Operation::Transpose { options, .. } = op {
        let perm: Vec<i32> = if let Some(opts) = options {
            if opts.permutation.is_empty() {
                (0..in_shape.len() as i32).rev().collect()
            } else {
                opts.permutation.iter().map(|&p| p as i32).collect()
            }
        } else {
            (0..in_shape.len() as i32).rev().collect()
        };
        let perm_bytes: Vec<u8> = perm.iter().flat_map(|v| v.to_le_bytes()).collect();
        let perm_tensor = ctx.add_constant(
            "transpose_perm",
            &[perm.len() as i32],
            tflite::TensorType::INT32,
            &perm_bytes,
        );
        inputs.push(perm_tensor as i32);
        return Ok(false);
    }

    // Slice: use SLICE (no strides) or STRIDED_SLICE (with strides)
    if let Some(handled) = ctx.build_slice_op(op, tensor_map, operator_offsets, in_tensor, inputs) {
        return Ok(handled);
    }

    // Pad: add paddings tensor as input[1]
    if let Operation::Pad {
        beginning_padding,
        ending_padding,
        ..
    } = op
    {
        let rank = beginning_padding.len();
        let mut pad_data = Vec::with_capacity(rank * 2 * 4);
        for i in 0..rank {
            pad_data.extend_from_slice(&(beginning_padding[i] as i32).to_le_bytes());
            pad_data.extend_from_slice(&(ending_padding[i] as i32).to_le_bytes());
        }
        let pad_tensor = ctx.add_constant(
            "pad_paddings",
            &[rank as i32, 2],
            tflite::TensorType::INT32,
            &pad_data,
        );
        inputs.push(pad_tensor as i32);
        return Ok(false);
    }

    // Reverse: add axis tensor as input[1]
    if let Operation::Reverse { options, .. } = op {
        let axes: Vec<i32> = if let Some(opts) = options {
            opts.axes
                .as_deref()
                .unwrap_or(&[])
                .iter()
                .map(|&a| a as i32)
                .collect()
        } else {
            vec![]
        };
        let axes_data: Vec<u8> = if axes.is_empty() {
            vec![0i32].iter().flat_map(|v| v.to_le_bytes()).collect()
        } else {
            axes.iter().flat_map(|v| v.to_le_bytes()).collect()
        };
        let ax_len = if axes.is_empty() { 1 } else { axes.len() };
        let ax_tensor = ctx.add_constant(
            "reverse_axes",
            &[ax_len as i32],
            tflite::TensorType::INT32,
            &axes_data,
        );
        inputs.push(ax_tensor as i32);
        return Ok(false);
    }

    // Tile: add multiples tensor as input[1]
    if let Operation::Tile { repetitions, .. } = op {
        let reps: Vec<i32> = repetitions.iter().map(|&r| r as i32).collect();
        let reps_bytes: Vec<u8> = reps.iter().flat_map(|v| v.to_le_bytes()).collect();
        let reps_tensor = ctx.add_constant(
            "tile_multiples",
            &[reps.len() as i32],
            tflite::TensorType::INT32,
            &reps_bytes,
        );
        inputs.push(reps_tensor as i32);
        return Ok(false);
    }

    // ArgMax/ArgMin: add axis tensor as input[1]
    if let Operation::ArgMax { axis, .. } | Operation::ArgMin { axis, .. } = op {
        let axis_bytes = (*axis as i32).to_le_bytes();
        let axis_tensor =
            ctx.add_constant("argmax_axis", &[1], tflite::TensorType::INT32, &axis_bytes);
        inputs.push(axis_tensor as i32);
        return Ok(false);
    }

    // CumulativeSum: add axis tensor as input[1]
    if let Operation::CumulativeSum { axis, .. } = op {
        let axis_bytes = (*axis as i32).to_le_bytes();
        let axis_tensor =
            ctx.add_constant("cumsum_axis", &[1], tflite::TensorType::INT32, &axis_bytes);
        inputs.push(axis_tensor as i32);
        return Ok(false);
    }

    // Resample2d: add size tensor as input[1]
    if let Operation::Resample2d { options, .. } = op {
        let opts = options.as_ref().cloned().unwrap_or_default();
        let sizes: Vec<i32> = if let Some(ref s) = opts.sizes {
            s.iter().map(|&v| v as i32).collect()
        } else if !opts.scales.is_empty() {
            let h = if in_shape.len() >= 2 {
                (in_shape[in_shape.len() - 2] as f32 * opts.scales[0]) as i32
            } else {
                1
            };
            let w = if in_shape.len() >= 1 {
                (in_shape[in_shape.len() - 1] as f32 * opts.scales[1]) as i32
            } else {
                1
            };
            vec![h, w]
        } else {
            vec![]
        };
        if !sizes.is_empty() {
            let sizes_bytes: Vec<u8> = sizes.iter().flat_map(|v| v.to_le_bytes()).collect();
            let sizes_tensor = ctx.add_constant(
                "resize_sizes",
                &[sizes.len() as i32],
                tflite::TensorType::INT32,
                &sizes_bytes,
            );
            inputs.push(sizes_tensor as i32);
        }
        return Ok(false);
    }

    Ok(false)
}

fn datatype_to_tflite(dt: DataType) -> Result<tflite::TensorType, GraphError> {
    Ok(match dt {
        DataType::Float32 => tflite::TensorType::FLOAT32,
        DataType::Float16 => tflite::TensorType::FLOAT16,
        DataType::Int32 => tflite::TensorType::INT32,
        DataType::Uint32 => tflite::TensorType::UINT32,
        DataType::Int64 => tflite::TensorType::INT64,
        DataType::Uint64 => tflite::TensorType::UINT64,
        DataType::Int8 => tflite::TensorType::INT8,
        DataType::Uint8 => tflite::TensorType::UINT8,
        DataType::Int4 => tflite::TensorType::INT4,
        DataType::Uint4 => Err(GraphError::UnsupportedDataType {
            data_type: DataType::Uint4,
            backend: Backend::Litert,
        })?,
    })
}

/// Parse an MLNumber (JSON number or string like "Infinity", "NaN") as f64.
fn parse_mlnumber(value: Option<&serde_json::Value>) -> Option<f64> {
    let v = value?;
    if let Some(n) = v.as_f64() {
        return Some(n);
    }
    let s = v.as_str()?.trim().to_ascii_lowercase();
    match s.as_str() {
        "inf" | "+inf" | "infinity" | "+infinity" => Some(f64::INFINITY),
        "-inf" | "-infinity" => Some(f64::NEG_INFINITY),
        "nan" => Some(f64::NAN),
        _ => s.parse::<f64>().ok(),
    }
}

fn dimensions_to_i32(shape: &[Dimension]) -> Vec<i32> {
    shape
        .iter()
        .map(|d| match d {
            Dimension::Static(n) => *n as i32,
            Dimension::Dynamic(_) => -1,
        })
        .collect()
}

